function R = run_phase5b_production(tag, varargin)
%RUN_PHASE5B_PRODUCTION  End-to-end Phase-5b production-v2 driver (Task C11).
%   R = RUN_PHASE5B_PRODUCTION(tag) builds every Phase-5b protection output
%   from the frozen Phase-4 production archive (read-only) and writes
%   results/phase5_protection_v2/ via PHASE5B_WRITER:
%     10 CSVs (device_registry, relay_settings, fault_inputs,
%     relay_currents, coordination_matrix, coordination_margins,
%     breaker_duty, sensitivity, validation, NEW phase5b_effectiveness)
%     + manifest.json + run_log.txt + sha256.txt, plus TCC plots via
%     PHASE5B_TCC into plots/ (regenerated deterministically; hashes
%     recorded; the C10 plots are overwritten in place inside the v2 dir
%     only — either choice is allowed if documented, and regeneration is
%     the choice recorded here).
%
%   R = RUN_PHASE5B_PRODUCTION(tag, 'overwrite', true) re-runs into the
%   existing results/phase5_protection_v2 directory. Without the flag, an
%   existing directory errors error('phase5b_production:exists').
%   Default tag 'production-v2' (manifest tag only; the output directory is
%   fixed results/phase5_protection_v2; results/phase5_protection stays
%   frozen untouched).
%
%   LOCKED RECOMPUTE CHAIN (ledger ruling — implemented exactly, read ALL
%   consumers first, modified nothing):
%   (a) phase5_import T40 (frozen v1, read-only; 40-row backbone).
%   (b) phase5b_registry v2 devices (C2 study rows + C7 physical rows).
%   (c) Study pickups resolved via phase5b_pickup C4 rules (GEN 17170.8 =
%       1.20x14309 Imax; GSUT 1380 = 1.2xmax(1150, 870.7726); GIS 1.2xFL
%       LINE_Q9 formula via 1600/1; EF 5 A retained sensitive case; EF TMS
%       0.15 from PICKUP, never registry 0.20) and injected (resolved
%       pickup/TMS/curve) into a devices copy — the registry itself is
%       never edited. Siemens-baseline rows (GEN-51-SIEMENS-BL, DT-??) are
%       NEVER dispatched to phase5_time: the DT-?? path is excluded from
%       time/margin computation with a ?? reason (use_phase5_time false is
%       asserted, and no phase5_time call ever sees a DT-?? curve).
%   (d) Relay currents via phase5_ct arithmetic with v2 CTs (15000 gen /
%       1600 GSUT-GIS): branch primaries from the coord matrix sides
%       (I_primary = I_secondary x CT_device). The frozen phase5_ct_table
%       wrapper rejects 1600 by its locked ratio guard (15000/16000 only),
%       and frozen files are never modified, so conversion calls phase5_ct
%       directly — the single source of truth phase5_ct_table delegates to
%       (concern C11-REL-CT in the task report).
%   (e) Operating times via frozen phase5_time (TMS 0.20 study phase,
%       0.15 EF) inside frozen phase5_coord.
%   (f) Coordination via frozen phase5_coord on the v2-resolved devices.
%   (g) Duty via phase5b_duty wrapper (52G 100 kA SOURCE-BACKED +
%       equipment/interrupting column split).
%   (h) Sensitivity: BLOCKED on frozen phase5_sensitivity reuse (evidence:
%       phase5_sensitivity.m:137 'IsUp = pkUp / 2000', :190 'primUp / 2000',
%       :193 reason 'upstream-GSUT-HV-51-2000/1-untouched', comments :9/:11
%       '2000/1 STUDY CTs' — v1 CT hard-coded on the upstream leg instead of
%       reading device ct_ratio, which is 1600 in v2; pinned by
%       test_phase5b_writer). The frozen file is NOT modified; the
%       v2-adapted GEN-scope sensitivity is computed in the local
%       SENSITIVITY_V2 engine below (reads device pickups/CTs, 1600 upstream
%       dial, EF TMS 0.15; frozen phase5_ct/phase5_time only).
%   (i) Effectiveness via phase5b_effectiveness (single branch-phasor call,
%       ~5 min, reused across all rows inside the module; F4 uses B1/B2
%       section rows, never the LINE_total cancellation residual).
%   (j) phase5b_writer writes all v2 CSVs + effectiveness table + manifest
%       (input SHA = v1 production SHA + v1-outputs reference; code hashes
%       incl. phase5b_* + v1 modules used) + sha256 + run_log under
%       results/phase5_protection_v2/ (tag production-v2).
%
%   Validation/tests: live phase5_validate() supplies the validation CSV
%   and manifest reference (frozen framework regression; v2 legs B01+ arrive
%   in C12 phase5b_validate); run_phase5_tests() runs after the tables and
%   TCC plots but BEFORE phase5b_writer, so NP/NF land in run_log.txt
%   before sha256.txt is hashed (never appended after hashing). Counts
%   are recorded honestly, never gated-to-pass here. All errors raised here
%   are 'phase5b'-prefixed (reuse of frozen v1 functions keeps 'phase5' IDs).
t0run = tic;
if nargin < 1 || isempty(tag)
    tag = 'production-v2';
end
if isstring(tag) && isscalar(tag), tag = char(tag); end
if ~(ischar(tag) && isrow(tag) && ~isempty(tag))
    error('phase5b_production:badTag', 'tag must be a non-empty char rowvec (manifest tag).');
end
overwrite = false;
for k = 1:2:numel(varargin)
    nm = varargin{k};
    if isstring(nm), nm = char(nm); end
    if k + 1 > numel(varargin)
        error('phase5b_production:args', 'Name-value options need a value.');
    end
    vv = varargin{k + 1};
    switch lower(nm)
        case 'overwrite'
            overwrite = logical(vv);
        otherwise
            error('phase5b_production:args', 'Unknown option ''%s''.', nm);
    end
end
root = ashuganj_root();
outDir = fullfile(root, 'results', 'phase5_protection_v2');
if exist(outDir, 'dir') == 7 && ~overwrite
    error('phase5b_production:exists', ...
        'Output directory %s exists; re-run with ''overwrite'', true.', outDir);
end
% ---- INPUT production manifest SHA, read-only ----
prodMan = fullfile(root, 'results', 'phase4_fault', 'production', 'manifest.json');
prodSha = fullfile(root, 'results', 'phase4_fault', 'production', 'sha256.txt');
if exist(prodMan, 'file') ~= 2
    error('phase5b_production:input', 'production manifest missing (read-only input): %s', prodMan);
end
if exist(prodSha, 'file') ~= 2
    error('phase5b_production:input', 'production sha256.txt missing (read-only input): %s', prodSha);
end
inputManifestSha = sha256file(prodMan);
inputShaLines = strsplit(strtrim(fileread(prodSha)), '\n');
inputShaLines = inputShaLines(:)';
% ---- v1-outputs reference (read-only; frozen v1 dir never modified) ----
v1Man = fullfile(root, 'results', 'phase5_protection', 'manifest.json');
v1Sha = fullfile(root, 'results', 'phase5_protection', 'sha256.txt');
if exist(v1Man, 'file') ~= 2
    error('phase5b_production:input', 'v1 outputs manifest missing (read-only reference): %s', v1Man);
end
if exist(v1Sha, 'file') ~= 2
    error('phase5b_production:input', 'v1 outputs sha256.txt missing (read-only reference): %s', v1Sha);
end
v1OutputsManifestSha = sha256file(v1Man);
v1OutputsShaLines = strsplit(strtrim(fileread(v1Sha)), '\n');
v1OutputsShaLines = v1OutputsShaLines(:)';
% ---- (a)+(b) backbone import (40 rows) + v2 registry (33 devices) ----
Rreg = phase5b_registry();
Ti = phase5_import(root);
if height(Ti) ~= 40
    error('phase5b_production:matrix', 'phase5_import backbone row count %d ~= 40.', height(Ti));
end
if numel(Rreg.devices) ~= 33
    error('phase5b_production:registry', 'phase5b_registry device count %d ~= 33 (7 study + 26 physical).', numel(Rreg.devices));
end
% ---- Iseq0_kA + r_kappa_ip joins from production currents ----
TiJ = join_production_peaks(root, Ti);
% ---- FL anchors live from production ct_data (frozen flows) ----
anchors = read_anchors(root);
% Imin anchors, coord-consistent (totals-based; branch legs affect times only).
[IminPhase, IminEarth] = pickup_anchors(TiJ);
% ---- (c) C4 PRODUCTION-V2 pickups, stamped into a devices copy ----
[devicesProd, setRows, settingsLines] = production_settings_v2(Rreg, anchors, IminPhase, IminEarth);
% ---- Tables 1-3: registry / settings / fault_inputs ----
Tregistry = registry_table_v2(Rreg);
TfaultInputs = table(Ti.fault_location, Ti.fault_type, Ti.caseID, Ti.m, ...
    Ti.stage, Ti.I_primary_kA, Ti.I_primary_A, Ti.provenance, ...
    repmat({'PRIMARY'}, height(Ti), 1), ...
    'VariableNames', {'fault_location', 'fault_type', 'caseID', 'm', ...
    'stage', 'I_primary_kA', 'I_primary_A', 'provenance', 'scope'});
% ---- (f) Coordination on v2-resolved settings + joined Iseq0 ----
[Mtrx, Mrg] = phase5_coord(devicesProd, TiJ);
Mtrx.provenance = repmat({['DERIVED:phase5_coord-branch-through-current-' ...
    'margin-CTI-0.3s-SOURCE-BACKED-confirmed-Phase-4-import-v2-CTs-15000/1600']}, height(Mtrx), 1);
Mtrx.scope = repmat({'PRIMARY'}, height(Mtrx), 1);
Mrg.provenance = repmat({['DERIVED:phase5_coord-margin-dt-t_up-minus-t_down-' ...
    'CTI-0.3s-SOURCE-BACKED-confirmed-Phase-4-import']}, height(Mrg), 1);
Mrg.scope = repmat({'PRIMARY'}, height(Mrg), 1);
% ---- (d) Relay currents traced from the graded matrix sides (v2 CTs) ----
TrelayCurrents = relay_currents_table_v2(Mtrx, TiJ);
% ---- (g) Duty via the phase5b_duty wrapper (52G 100 kA + split) ----
Dduty12 = phase5b_duty(TiJ);
Dduty = duty_provenance_split(Dduty12);
% ---- (h) v2-adapted sensitivity (BLOCKED fallback; frozen module untouched) ----
Tsens = phase5b_sensitivity_v2(TiJ, devicesProd, Rreg);
% ---- (i) Effectiveness (single branch-phasor recompute inside, ~5 min) ----
E = phase5b_effectiveness(Ti, Rreg.devices);
% ---- Live frozen validation -> validation CSV + manifest reference ----
V = phase5_validate();
vPass = sum([V.legs.pass]); vTotal = numel(V.legs);
vIds = strjoin({V.legs.id}, ',');
vNote = sprintf('live phase5_validate %d/%d legs pass (%s); v2 legs B01+ arrive in C12 phase5b_validate', vPass, vTotal, vIds);
Tvalid = table({V.legs.id}', double([V.legs.pass]'), [V.legs.residual]', ...
    {V.legs.note}', ...
    repmat({'DERIVED:phase5_validate-live-run-R0-V1-V15-frozen-framework-regression'}, vTotal, 1), ...
    repmat({'PRIMARY'}, vTotal, 1), ...
    'VariableNames', {'leg', 'pass', 'residual', 'note', 'provenance', 'scope'});
% ---- TCC plots regenerate deterministically into the v2 plots dir ----
plotDir = fullfile(outDir, 'plots');
Stcc = phase5b_tcc(plotDir, root);
tccPhysHash = sha256file(Stcc.physical_png);
tccStudyHash = sha256file(Stcc.study_png);
tccMeta = struct('physical_png', Stcc.physical_png, 'study_png', Stcc.study_png, ...
    'physical_sha256', tccPhysHash, 'study_sha256', tccStudyHash, ...
    'regenerated', true, ...
    'choice_note', sprintf(['TCC plots REGENERATED deterministically via phase5b_tcc ' ...
        '(C10 outputs overwritten in place inside the v2 dir only): %s [%s], %s [%s]'], ...
        Stcc.physical_png, tccPhysHash, Stcc.study_png, tccStudyHash));
settingsLines{end + 1} = sprintf('TCC plots regenerated via phase5b_tcc: %s [%s], %s [%s]', ... %#ok<AGROW>
    Stcc.physical_png, tccPhysHash, Stcc.study_png, tccStudyHash);
% ---- Tests run BEFORE the writer so counts land in run_log pre-hash ----
[NP, NF] = run_phase5_tests();
% ---- Writer (provenance whitelist incl. USER_ASSERTED_PENDING_DOC) ----
tables = struct('registry', Tregistry, 'settings', setRows, ...
    'faultInputs', TfaultInputs, 'relayCurrents', TrelayCurrents, ...
    'coordMatrix', Mtrx, 'coordMargins', Mrg, 'duty', Dduty, ...
    'sensitivity', Tsens, 'validation', Tvalid, 'effectiveness', E);
meta = struct('tag', tag, 'inputManifestSha', inputManifestSha, ...
    'inputShaLines', {inputShaLines}, ...
    'v1OutputsManifestSha', v1OutputsManifestSha, ...
    'v1OutputsShaLines', {v1OutputsShaLines}, ...
    'validation', struct('pass', vPass, 'total', vTotal, 'note', vNote), ...
    'testCounts', struct('NP', NP, 'NF', NF), ...
    'settingsLines', {settingsLines}, ...
    'extraNotes', {{['TCC plots (tcc_physical.png, tcc_study.png) in plots/ regenerated deterministically ' ...
        'via phase5b_tcc; PNG hashes recorded in manifest.tccPlots + run_log (choice documented per C11).'], ...
        ['Sensitivity is v2-adapted GEN scope (frozen phase5_sensitivity BLOCKED for v2: hard-codes v1 2000 CT ' ...
        'upstream; never modified; evidence pinned in test_phase5b_writer).'], ...
        ['Siemens DT baseline GEN-51-SIEMENS-BL (DT-??, tdef 3.00 s ??) excluded from all time/margin computation ' ...
        'with ?? reason; operating times via frozen phase5_time on study SI rows only.'], ...
        ['Relay-current secondaries via frozen phase5_ct arithmetic (phase5_ct_table rejects v2 1600 CTs by ' ...
        'locked guard; never modified; concern C11-REL-CT).'], ...
        'v1 outputs dir results/phase5_protection frozen untouched (read-only reference only).'}}, ...
    'tcc', tccMeta);
W = phase5b_writer(outDir, tables, meta);
secs = toc(t0run);
fprintf(['run_phase5b_production %s: registry=%d settings=%d inputs=%d currents=%d ' ...
    'matrix=%d margins=%d duty=%d sens=%d valid=%d/%d eff=%d tests NP=%d NF=%d in %s (%.1f s)\n'], ...
    tag, height(Tregistry), height(setRows), height(TfaultInputs), ...
    height(TrelayCurrents), height(Mtrx), height(Mrg), height(Dduty), ...
    height(Tsens), vPass, vTotal, height(E), NP, NF, outDir, secs);
R = struct('dir', outDir, 'tag', tag, 'rowCounts', W.rowCounts, ...
    'validatePass', vPass, 'validateTotal', vTotal, 'NP', NP, 'NF', NF, ...
    'physPng', Stcc.physical_png, 'studyPng', Stcc.study_png, 'secs', secs);
end

function TiJ = join_production_peaks(root, Ti)
%JOIN_PRODUCTION_PEAKS  Iseq0_kA + r_kappa_ip from currents CSV (v1 T(b)+(c)).
%   Backbone-first dedup identical to phase5_import, inner join on
%   (caseID,location,fault_type). Every import row must hit, else
%   phase5b_production:join (never silently NaN-filled).
Fp = fullfile(root, 'results', 'phase4_fault', 'production', 'phase4_fault_currents.csv');
C = readtable(Fp);
for k = 1:numel({'fault_type', 'location', 'm', 'caseID', 'stage', 'Iseq0_kA', 'r_kappa_ip'})
    need = {'fault_type', 'location', 'm', 'caseID', 'stage', 'Iseq0_kA', 'r_kappa_ip'};
    if ~any(strcmp(C.Properties.VariableNames, need{k}))
        error('phase5b_production:schema', 'production currents CSV missing column %s.', need{k});
    end
end
Cb = C(strcmp(C.stage, 'Ikpp') & C.m == 0.5, :);
keys = strcat(Cb.caseID, '|', Cb.location, '|', Cb.fault_type);
[~, ia] = unique(keys, 'stable');
Cb = Cb(ia, :);
n = height(Ti);
Iseq0 = NaN(n, 1); rkp = NaN(n, 1);
tloc = tocell(Ti.fault_location); ttyp = tocell(Ti.fault_type); tcs = tocell(Ti.caseID);
bloc = tocell(Cb.location); btyp = tocell(Cb.fault_type); bcs = tocell(Cb.caseID);
for i = 1:n
    hit = find(strcmp(bcs, tcs{i}) & strcmp(bloc, tloc{i}) & strcmp(btyp, ttyp{i}), 1, 'first');
    if isempty(hit)
        error('phase5b_production:join', ...
            'production currents join missed %s %s %s (backbone keys diverged).', ...
            tcs{i}, tloc{i}, ttyp{i});
    end
    Iseq0(i) = Cb.Iseq0_kA(hit);
    rkp(i) = Cb.r_kappa_ip(hit);
end
if any(~isfinite(Iseq0)) || any(~isfinite(rkp))
    error('phase5b_production:join', 'joined Iseq0_kA/r_kappa_ip must be finite on all 40 backbone rows.');
end
TiJ = Ti;
TiJ.Iseq0_kA = Iseq0;
TiJ.r_kappa_ip = rkp;
end

function anchors = read_anchors(root)
%READ_ANCHORS  Frozen-flow FL_anchor_kA per through_path, live from ct_data.
G = readtable(fullfile(root, 'results', 'phase4_fault', 'production', 'phase4_ct_data.csv'));
if ~all(ismember({'through_path', 'FL_anchor_kA'}, G.Properties.VariableNames))
    error('phase5b_production:schema', 'production ct_data CSV missing through_path/FL_anchor_kA.');
end
paths = {'GEN_Q', 'GSUT_HV', 'GRID_Q', 'LINE_Q9'};
anchors = struct();
tp = tocell(G.through_path);
for k = 1:numel(paths)
    u = unique(G.FL_anchor_kA(strcmp(tp, paths{k})));
    u = u(isfinite(u));
    if numel(u) ~= 1
        error('phase5b_production:anchor', ...
            'through_path %s must carry exactly one FL_anchor_kA (got %d).', paths{k}, numel(u));
    end
    anchors.(paths{k}) = u;
end
end

function [IminPhase, IminEarth] = pickup_anchors(TiJ)
%PICKUP_ANCHORS  Must-detect anchors (v1 T6 convention, totals-based).
%   IminPhase: min over phase-fault totals (LLL/LL/LLG, never LG earth).
%   IminEarth: LG-only min over LG totals (phase5b_pickup EF contract).
typs = tocell(TiJ.fault_type);
ph = strcmp(typs, 'LLL') | strcmp(typs, 'LL') | strcmp(typs, 'LLG');
IfA = double(TiJ.I_primary_A(:));
if any(ph)
    IminPhase = min(IfA(ph));
else
    IminPhase = min(IfA);
end
lg = strcmp(typs, 'LG');
if any(lg)
    IminEarth = min(IfA(lg));
else
    IminEarth = 7.27200442799167;
end
end

function [devicesProd, setRows, settingsLines] = production_settings_v2(Rreg, anchors, IminPhase, IminEarth)
%PRODUCTION_SETTINGS_V2  (c): C4 pickups stamped on a devices copy.
%   Registry struct itself never edited. Siemens-baseline rows NEVER
%   dispatched to phase5_time (asserted use_phase5_time false; no time call).
devs = Rreg.devices;
ids = {devs.device_id};
dGen = devs(strcmp(ids, 'GEN-51'));
dEf = devs(strcmp(ids, 'GEN-51N'));
dHv = devs(strcmp(ids, 'GSUT-HV-51'));
dQ0 = devs(strcmp(ids, 'GIS-Q0-51'));
dBl = devs(strcmp(ids, 'GEN-51-SIEMENS-BL'));
% GEN-51-SI: 1.20 x Imax 14309 = 17170.8 A (max-operating-current basis).
Pgen = phase5b_pickup(dGen, double(Rreg.gen.Imax_A), IminPhase);
if abs(Pgen.setting - 17170.8) / 17170.8 > 1e-9
    error('phase5b_production:pickup', 'GEN-51 v2 pickup %.4f A ~= 17170.8 A.', Pgen.setting);
end
if abs(Pgen.tms - 0.20) > 1e-12 || ~strcmp(Pgen.curve, 'SI') || ~Pgen.use_phase5_time
    error('phase5b_production:pickup', 'GEN-51 v2 must be SI/TMS-0.20/inverse-allowed.');
end
if abs(Pgen.setting_sec_A - Pgen.setting / 15000) / Pgen.setting_sec_A > 1e-12
    error('phase5b_production:pickup', 'GEN-51 secondary must be Is/15000.');
end
% GEN-51N-SI-STUDY: 5 A retained sensitive case; EF TMS 0.15 FROM PICKUP
% (registry GEN-51N tms is 0.20 — the pickup value governs, asserted here).
Pef = phase5b_pickup(dEf, 0, IminEarth);
if abs(Pef.setting - 5) > 1e-12
    error('phase5b_production:pickup', 'GEN-51N v2 pickup %.6f A ~= 5 A.', Pef.setting);
end
if abs(Pef.tms - 0.15) > 1e-12 || abs(Pef.ef_tms - 0.15) > 1e-12
    error('phase5b_production:pickup', 'GEN-51N v2 EF TMS must be 0.15 from pickup (not registry 0.20).');
end
if abs(double(dEf.tms) - 0.20) > 1e-12
    error('phase5b_production:pickup', 'GEN-51N registry tms must be 0.20 (EF 0.15 comes from pickup).');
end
% GSUT-HV-51: 1.2 x max(rated 1150 A, GSUT_HV anchor) = 1380 A via 1600/1.
hvAnchor = anchors.GSUT_HV * 1000;
Phv = phase5b_pickup(dHv, hvAnchor, IminPhase);
if abs(Phv.setting - 1380) / 1380 > 1e-9
    error('phase5b_production:pickup', 'GSUT-HV-51 v2 pickup %.4f A ~= 1380 A.', Phv.setting);
end
if abs(Phv.tms - 0.20) > 1e-12 || ~strcmp(Phv.curve, 'SI') || ~Phv.use_phase5_time
    error('phase5b_production:pickup', 'GSUT-HV-51 v2 must be SI/TMS-0.20/inverse-allowed.');
end
if abs(Phv.setting_sec_A - 1380 / 1600) / (1380 / 1600) > 1e-12
    error('phase5b_production:pickup', 'GSUT-HV-51 secondary must be 1380/1600.');
end
% GIS-Q0-51 V2 PATH: 1.2 x LINE_Q9 FL_anchor via 1600/1 (GIS formula).
q0Anchor = anchors.LINE_Q9 * 1000;
Pq0 = phase5b_pickup(dQ0, q0Anchor, IminPhase);
if abs(Pq0.setting / q0Anchor - 1.2) > 1e-12
    error('phase5b_production:pickup', 'GIS-Q0-51 v2 pickup must be 1.2x FL_anchor.');
end
if abs(Pq0.tms - 0.20) > 1e-12 || ~strcmp(Pq0.curve, 'SI') || ~Pq0.use_phase5_time
    error('phase5b_production:pickup', 'GIS-Q0-51 v2 must be SI/TMS-0.20/inverse-allowed.');
end
if abs(Pq0.setting_sec_A - Pq0.setting / 1600) / Pq0.setting_sec_A > 1e-12
    error('phase5b_production:pickup', 'GIS-Q0-51 secondary must be Is/1600.');
end
% Siemens DT baseline: resolved for the settings RECORD ONLY — inverse
% prohibited (use_phase5_time false asserted; never dispatched to phase5_time).
Pbl = phase5b_pickup(dBl, anchors.GEN_Q * 1000, IminPhase);
if abs(Pbl.setting - 17171) > 1e-9
    error('phase5b_production:pickup', 'GEN-51-SIEMENS-BL pickup %.4f A ~= 17171 A.', Pbl.setting);
end
if ~(islogical(Pbl.use_phase5_time) && isscalar(Pbl.use_phase5_time) && ~Pbl.use_phase5_time)
    error('phase5b_production:pickup', 'GEN-51-SIEMENS-BL must carry use_phase5_time false (inverse prohibited).');
end
if ~strcmp(Pbl.curve, 'DT-??')
    error('phase5b_production:pickup', 'GEN-51-SIEMENS-BL must carry curve DT-??.');
end
% Stamp resolved pickup/TMS/curve into a copy (registry never edited).
% EF TMS 0.15 from pickup (not registry 0.20) is stamped into .tms so the
% frozen coord/time path grades the pickup-consistent dial.
devicesProd = devs;
devicesProd(strcmp(ids, 'GEN-51')).pickup_A = Pgen.setting;
devicesProd(strcmp(ids, 'GEN-51')).tms = Pgen.tms;
devicesProd(strcmp(ids, 'GEN-51')).curve = Pgen.curve;
devicesProd(strcmp(ids, 'GEN-51N')).pickup_A = Pef.setting;
devicesProd(strcmp(ids, 'GEN-51N')).tms = Pef.tms;
devicesProd(strcmp(ids, 'GEN-51N')).curve = Pef.curve;
devicesProd(strcmp(ids, 'GSUT-HV-51')).pickup_A = Phv.setting;
devicesProd(strcmp(ids, 'GSUT-HV-51')).tms = Phv.tms;
devicesProd(strcmp(ids, 'GSUT-HV-51')).curve = Phv.curve;
devicesProd(strcmp(ids, 'GIS-Q0-51')).pickup_A = Pq0.setting;
devicesProd(strcmp(ids, 'GIS-Q0-51')).tms = Pq0.tms;
devicesProd(strcmp(ids, 'GIS-Q0-51')).curve = Pq0.curve;
setRows = settings_table_v2(devs, Pgen, Pef, Phv, Pq0, Pbl);
settingsLines = {
    sprintf('GEN-51-SI phase pickup %.2f A-primary (1.20xImax-14309A max-operating-current; %s)', Pgen.setting, Pgen.basis)
    sprintf('GEN-51-SI secondary %.5f A via 15000/1 (converges with Siemens DT 17171 A; characteristic SI-vs-DT differs)', Pgen.setting_sec_A)
    sprintf('GEN-51N-SI-STUDY earth pickup %.2f A-primary (SENSITIVE retained; %s)', Pef.setting, Pef.basis)
    sprintf('GEN-51N-SI-STUDY TMS %.2f from phase5b_pickup (NOT registry 0.20); secondary %.6f A via 15000/1', Pef.tms, Pef.setting_sec_A)
    sprintf('GSUT-HV-51 phase pickup %.2f A-primary (1.2xmax(rated 1150 A, GSUT_HV anchor %.4f A) via 1600/1 SOURCE-BACKED; %s)', Phv.setting, hvAnchor, Phv.source)
    sprintf('GSUT-HV-51 secondary %.4f A (1380/1600)', Phv.setting_sec_A)
    sprintf('GIS-Q0-51 phase pickup %.4f A-primary (V2 1.2x LINE_Q9 FL_anchor %.6f A from phase4_ct_data.csv via 1600/1 SOURCE-BACKED; never 2400 A rated-proxy)', Pq0.setting, q0Anchor)
    sprintf('GIS-Q0-51 secondary %.6f A (Is/1600)', Pq0.setting_sec_A)
    sprintf('GEN-51-SIEMENS-BL DT baseline %.0f A-primary (%.4f A-sec via 15000/1; tdef %.2f s ?? PENDING-COORDINATION; inverse PROHIBITED — never dispatched to phase5_time)', Pbl.setting, Pbl.setting_sec_A, Pbl.tdef)
    sprintf('FL anchors (phase4_ct_data.csv FL_anchor_kA, frozen flows): GEN_Q %.4f, GSUT_HV %.5f, GRID_Q %.5f, LINE_Q9 %.6f kA', anchors.GEN_Q, anchors.GSUT_HV, anchors.GRID_Q, anchors.LINE_Q9)
    sprintf('Imin anchors: phase %.2f A (LLL/LL/LLG totals min); earth %.5f A (LG totals min per EF contract)', IminPhase, IminEarth)
    'TMS study uniform 0.20 phase (ENGINEERING_ASSUMPTION Status-C initial, registry-stamped) / 0.15 EF (pickup-resolved); curve SI (STUDY constants, never manufacturer)'
    'CTI 0.3 s SOURCE-BACKED confirmed (ledger CTI-0.3s); v2 CTs 15000/1 GEN + 1600/1 GSUT-GIS SOURCE-BACKED, 16000/1 LEGACY fenced sensitivity only'
    'Breaker duty: Q0 (52-1) NOT DETERMINABLE interrupting + 52G/GCB-10BAC10 100 kA sym breaking SOURCE-BACKED; peak r_kappa_ip borrowed-shape informational only, never duty input'
    'CSV dialect: RFC-4180 comma-separated; text fields with commas are double-quoted. MATLAB readers must use readtable(fp,''Delimiter'','','') because the auto-delimiter sniffer misparses quoted-comma rows.'
    };
end

