sets = [Pgen.setting; Pef.setting; Phv.setting; Pq0.setting; Pbl.setting; NaN; NaN; NaN];
units = {'A-primary'; 'A-primary'; 'A-primary'; 'A-primary'; 'A-primary'; ''; ''; ''};
basis = {Pgen.basis; Pef.basis; Phv.basis; Pq0.basis; Pbl.basis; ...
    'NOT DETERMINABLE FROM AVAILABLE DATA:GIS-Q0-50-high-set-DISABLED-unless-justified'; ...
