val = {[Pgen.validation ';tms-0.20-study-SI-via-15000/1']; ...
    [Pef.validation ';tms-0.15-study-SI-via-15000/1-EF-pickup-resolved']; ...
    [Phv.validation ';tms-0.20-study-SI-via-1600/1']; ...
    [Pq0.validation ';tms-0.20-study-SI-via-1600/1']; ...
    [Pbl.validation ';tdef-3.00s-??-PENDING-COORDINATION-inverse-prohibited-never-phase5_time']; ...
    'DISABLED-unless-justified;no high-set invented'; ...
    'NOTE-only;no settings invented'; ...
    'MONITORING-only;no settings invented'};
cts = [ctOf('GEN-51'); ctOf('GEN-51N'); ctOf('GSUT-HV-51'); ctOf('GIS-Q0-51'); ...
    ctOf('GEN-51-SIEMENS-BL'); ctOf('GIS-Q0-50'); NaN; NaN];
tms = [Pgen.tms; Pef.tms; Phv.tms; Pq0.tms; NaN; NaN; NaN; NaN];
cvs = {'SI'; 'SI'; 'SI'; 'SI'; 'DT-??'; ''; ''; ''};
prov = {['SOURCE-BACKED:protection-report-CT-15000/1-B22;' Pgen.source]; ...
    ['SOURCE-BACKED:protection-report-CT-15000/1-B22-EF;' Pef.source]; ...
    ['SOURCE-BACKED:GSUT-1600/1-cores-bay-dependent-default;' Phv.source]; ...
    ['SOURCE-BACKED:GIS-bay-1600/1-5P20-30VA-governing-study-CT;' Pq0.source]; ...
    ['USER_ASSERTED_PENDING_DOC:SIEMENS-Igt-1.14A+SIEMENS-tdef-3s-??-PENDING-DOC-INGEST;' Pbl.source]; ...
    'MISSING:GIS-Q0-50-high-set-no-source'; ...
