function [p, r, n] = legB09(E, Ti, R)
%LEG B09  51N/59N/64G split + F2-LG-backup consistency probe (C8 concern).
ids = {R.devices.device_id};
ge = R.devices(strcmp(ids, 'GEN-51N'));
cReg = isscalar(ge) && strcmp(ge.layer, 'STUDY') && ge.ct_ratio == 15000;
Pe = phase5b_pickup(ge, 0, 7.27200442799167);
cEF = (abs(Pe.setting - 5) < 1e-12) && strcmp(Pe.assumption_class, 'SENSITIVITY') ...
    && (abs(Pe.tms - 0.15) < 1e-12) && (abs(Pe.setting_sec_A - 5 / 15000) / (5 / 15000) < 1e-9);
cVT = true;
for k = 1:numel({'GEN-59N', 'GEN-64G', 'GEN-64R'})
    mid = {'GEN-59N', 'GEN-64G', 'GEN-64R'};
    d = R.devices(strcmp(ids, mid{k}));
    blob = [d.provenance ' ' d.protection_function];
    if ~(isscalar(d) && strcmp(d.layer, 'PHYSICAL') && isnan(d.pickup_A) && ~isempty(strfind(blob, '381.05')))
        cVT = false;
    end
end
d64 = R.devices(strcmp(ids, 'GEN-64G'));
c64 = ~isempty(strfind([d64.provenance ' ' d64.protection_function], 'NEVER-3I0')) ...
    || ~isempty(strfind([d64.provenance ' ' d64.protection_function], 'NEVER'));
g = effRow(E, 'F1', 'LG', 'LF360_GAT_OUT', 'GEN-51N-SI-STUDY');
locs = tocell(Ti.fault_location); typs = tocell(Ti.fault_type); cases = tocell(Ti.caseID);
iLG = find(strcmp(cases, 'LF360_GAT_OUT') & strcmp(locs, 'F1') & strcmp(typs, 'LG'), 1);
tExp = phase5_time(3 * Ti.leg_NER_earth_kA(iLG) * 1000, 5, 0.15, 'SI');
dEF = abs(g.backup_time_s - tExp) / g.backup_time_s;
cRow = ~isempty(g) && isfinite(g.backup_time_s) && (dEF < 1e-6);
t2lg = effRow(E, 'F2', 'LG', 'LF360_GAT_OUT', 'GSUT-HV-51');
cProbe = ~isempty(t2lg) && strcmp(t2lg.backup_function, 'GSUT-HV-51') && isfinite(t2lg.backup_time_s);
badN = E(strcmp(E.fault_location, 'F2') & strcmp(E.fault_type, 'LG') ...
    & (strcmp(E.backup_function, 'GEN-51N-SI-STUDY') | strcmp(E.backup_function, 'GEN-51N')), :);
cNever = isempty(badN) || height(badN) == 0;
p = cReg && cEF && cVT && c64 && cRow && cProbe && cNever;
r = dEF;
n = sprintf(['51N-SI-STUDY 5 A SENSITIVITY TMS 0.15 (sec 5/15000); 59N/64G/64R PHYSICAL NaN + 381.05 VT datum; ' ...
    '64G never-3I0; F1-LG EF backup %.4f s == phase5_time(3I0,5,0.15,SI) (rel %.2g); ' ...
    'F2-LG-backup consistency probe: F2 LG backup GSUT-HV-51 phase finite %.4f s, never GEN-51N'], g.backup_time_s, dEF, t2lg.backup_time_s);

