T = T.chk(~isempty(strfind(rep, sprintf('PASS = %d', nPASS))), 'report carries live PASS count');
T = T.chk(~isempty(strfind(rep, sprintf('NO-TRIP = %d', nNOTRIP))), 'report carries live NO-TRIP count');
T = T.chk(nFAIL + nNOTRIP + nNOPAIR + nNOTDET + nPASS == height(M), 'v2 distribution covers all rows');

% --- (2d) Live v2 duty split matches report ---
D = readtable(fullfile(root, 'results', 'phase5_protection_v2', 'phase5_breaker_duty.csv'), 'Delimiter', ',');
nQ0notdet = sum(strcmp(D.breaker_ref, 'Q0') & strcmp(D.verdict, 'NOT DETERMINABLE FROM AVAILABLE DATA'));
n52pass = sum(strcmp(D.breaker_ref, '52G') & strcmp(D.verdict, 'PASS'));
nNOTE = sum(strcmp(D.verdict, 'NOTE'));
T = T.chk(height(D) == 81, 'v2 duty 81 rows live');
T = T.chk(n52pass == 40, 'v2 52G PASS 40 live');
T = T.chk(nQ0notdet == 40, 'v2 Q0 NOT-DET 40 live');
T = T.chk(nNOTE == 1, 'v2 NOTE 1 live');
T = T.chk(~isempty(strfind(rep, '52G')) && ~isempty(strfind(rep, '100 kA')), 'report states 52G 100 kA duty');
T = T.chk(~isempty(strfind(rep, '40 x 52G PASS')) || ~isempty(strfind(rep, '40 PASS')) || ~isempty(strfind(rep, 'PASS = 40')) || ~isempty(strfind(rep, '52G PASS = 40')), 'report carries v2 52G PASS=40 split');

% --- (2e) Live v2 effectiveness split matches report ---
E = readtable(fullfile(root, 'results', 'phase5_protection_v2', 'phase5b_effectiveness.csv'), 'Delimiter', ',');
nSD = sum(strcmp(E.detection, 'STUDY-DETECTABILITY'));
nCD = sum(strcmp(E.detection, 'CONDITIONAL-DETECTABILITY'));
nND = sum(strcmp(E.detection, 'NOT-DETERMINABLE'));
T = T.chk(height(E) == 48, 'v2 effectiveness 48 rows live');
T = T.chk(nSD + nCD == 24 && nND == 24, 'v2 effectiveness 24 detectability / 24 NOT-DET live split');
T = T.chk((~isempty(strfind(rep, 'STUDY-DETECTABILITY')) || ~isempty(strfind(rep, 'CONDITIONAL-DETECTABILITY'))) && ~isempty(strfind(rep, 'NOT-DETERMINABLE')), 'report carries effectiveness vocabulary');
T = T.chk(~isempty(strfind(rep, '87G')) && ~isempty(strfind(rep, '87T')) && ~isempty(strfind(rep, '87B')) && ~isempty(strfind(rep, '7SD')), 'report explains 87G/87T/87B/7SD roles');

% --- (3) v1 appendix markers (fail on v1 body-only text by design) ---
T = T.chk(~isempty(strfind(rep, 'SUPERSEDED-BY-V2')), 'v1 appendix SUPERSEDED-BY-V2 marker present');
T = T.chk(~isempty(strfind(rep, '15023.75')), 'v1 frozen GEN pickup 15023.75 transcribed in appendix');
T = T.chk(~isempty(strfind(rep, '344')), 'v1 suite 344 transcribed in appendix');
T = T.chk(~isempty(strfind(low, 'v1 appendix')), 'v1 appendix section present');

