function M = phase5b_mindetect(T40, devices)
%PHASE5B_MINDETECT  Per-CT min-detect over zone-relevant branch currents (Phase-5b Task C6).
%   M = PHASE5B_MINDETECT(T40, devices) replaces the V9 totals-based
%   min-detect with one struct row per (device, element in
%   phase/residual/negseq). Each row carries the minimum BRANCH current
%   over zone-relevant faults, the C4 study pickup (via phase5b_pickup),
%   the margin (min_branch_A / pickup_A) and a verdict:
%     margin >= 1               -> 'DETECT'
%     margin <  1 (determinable) -> 'BLIND-SPOT-HONEST' (non-PASS, never tuned)
%     not determinable           -> 'NOT-DETERMINABLE' (honest, never invented)
%
%   Row fields (locked): device_id, element, zone_locs, branch_tag,
%   n_zone, n_used, min_branch_A, min_loc, min_type, min_case, pickup_A,
%   pickup_src, margin, verdict, determinable, reason.
%
%   Zone relevance (locked): GEN devices <- F1/F2 rows (GEN_Q branch leg
%   for phase; 3I0 = 3x NER series leg for residual; negseq branch NOT
%   DETERMINABLE); GSUT-HV <- F1/F2/F3 rows (GSUT_HV leg); GIS-Q0 <-
%   F3/F4/F5 rows (LINE_Q9 through-convention magnitude: |leg_LINE_total|
%   for non-F4 rows; F4 rows use the same column with the documented
%   caveat that toward-fault B1+B2 sums both infeeds, so the F4 value
%   overstates the GIS outfeed — the GIS min binds at F5 regardless).
%
%   Branch-current doctrine (hardened): ONLY leg_* columns of the
%   phase5_import T40 join are read (C5-pinned branch-through-current
%   semantics). Fault totals are never a proxy for relay current: no
%   fault-point magnitude column is referenced anywhere below.
%
%   Stored production legs are |Ia| magnitudes only (phase4_handoff
%   legRow). Phase-element candidate types are therefore LLL (symmetric:
%   all phases equal |Ia|) and LG (A-phase faulted; B/C ~ 0 per the
%   phase4 LG_branch0 diagnostic): on LL/LLG rows the stored |Ia| is the
%   UNFAULTED-phase current and understates what B/C phase elements see,
%   so LL/LLG phase coverage is recorded NOT-DETERMINABLE-by-type
%   (counted in the reason string, never silently dropped). Residual
%   scope is the LG sensitivity-defining fault (C4 51N study basis
%   must-detect-F1-LG); LLG residual rows are observed-but-out-of-scope
%   and their observed 3I0 minimum is quoted in the reason string as a
%   flagged limitation, never as a verdict input. Negseq branch I2 is
%   unavailable in T40/production CSVs; fault-point sequence current is
%   a total and is never derived per the branch-current doctrine, so
%   every negseq row is NOT-DETERMINABLE.
%
%   Pickups come from the phase5b_pickup C4 rules (registry carries NaN +
%   rule tags; nothing hard-coded here). Load anchors passed to the
%   pickup engine are locked study constants: GEN devices Imax 14309 A
%   (ledger GEN-Imax-14309); GSUT-HV-51 GSUT_HV flow anchor 870.7726 A
%   (rule takes max with rated 1150 A, so 1380 A); GIS-Q0-51 LINE_Q9 flow
%   anchor 869.9567 A; GEN-51N study 0 A (fixed 5 A retained case). The
%   Imin argument is the computed branch minimum itself (settings are
%   load-based, so there is no circularity; validation margins stay
%   consistent). Devices whose pickup errors (DISABLED high-set, notes,
%   boundaries) yield NOT-DETERMINABLE rows quoting the engine reason.
%
%   All errors are 'phase5b'-prefixed.
if nargin ~= 2
    error('phase5b_mindetect:args', 'usage: M = phase5b_mindetect(T40, devices).');
end
if ~istable(T40) || height(T40) < 1
    error('phase5b_mindetect:schema', 'T40 must be a non-empty table (phase5_import backbone).');
end
need = {'fault_location', 'fault_type', 'caseID', 'leg_GEN_kA', ...
    'leg_GSUT_HV_kA', 'leg_LINE_total_kA', 'leg_NER_earth_kA'};
for k = 1:numel(need)
    if ~any(strcmp(T40.Properties.VariableNames, need{k}))
        error('phase5b_mindetect:schema', 'T40 missing required branch column %s.', need{k});
    end
end
if ~isstruct(devices) || isempty(devices) || ~isfield(devices, 'device_id')
    error('phase5b_mindetect:devices', 'devices must be a non-empty struct array with device_id (registry rows).');
end

ELS = {'phase', 'residual', 'negseq'};
M = repmat(emptyRow(), 0, 1);
for d = 1:numel(devices)
    dev = devices(d);
    idraw = dev.device_id;
    if isstring(idraw) && isscalar(idraw)
        idraw = char(idraw);
    end
    if ~ischar(idraw) || isempty(strtrim(idraw))
        error('phase5b_mindetect:devices', 'devices(%d).device_id must be non-empty char.', d);
    end
    id = strtrim(idraw);
    [zone, legCol, zoneTag] = zoneOf(id);
    kind = kindOf(dev, id);
    for e = 1:numel(ELS)
        M(end + 1, 1) = buildRow(T40, dev, id, ELS{e}, zone, legCol, zoneTag, kind); %#ok<AGROW>
    end
end
end

function r = emptyRow()
r = struct('device_id', '', 'element', '', 'zone_locs', '', ...
    'branch_tag', '', 'n_zone', NaN, 'n_used', NaN, 'min_branch_A', NaN, ...
    'min_loc', '', 'min_type', '', 'min_case', '', 'pickup_A', NaN, ...
    'pickup_src', '', 'margin', NaN, 'verdict', 'NOT-DETERMINABLE', ...
    'determinable', false, 'reason', '');
end

function [zone, legCol, zoneTag] = zoneOf(id)
%ZONEOF  Locked zone relevance per device family.
if strncmp(id, 'GEN-', 4)
    zone = {'F1', 'F2'};
    legCol = 'leg_GEN_kA';
    zoneTag = 'F1+F2';
elseif strncmp(id, 'GSUT-HV', 7)
    zone = {'F1', 'F2', 'F3'};
    legCol = 'leg_GSUT_HV_kA';
    zoneTag = 'F1+F2+F3';
elseif strncmp(id, 'GIS-Q0', 6)
    zone = {'F3', 'F4', 'F5'};
    legCol = 'leg_LINE_total_kA';
    zoneTag = 'F3+F4+F5';
else
    zone = {};
    legCol = '';
    zoneTag = '';
end
end

function kind = kindOf(dev, id)
%KINDOF  Phase-OC vs earth-fault device kind (registry device_type wins; id fallback).
if isfield(dev, 'device_type')
    dt = dev.device_type;
    if isstring(dt) && isscalar(dt)
        dt = char(dt);
    end
    if ischar(dt) && strcmp(strtrim(dt), 'ef')
        kind = 'EF';
        return;
    end
    if ischar(dt) && (strcmp(strtrim(dt), 'oc') || strcmp(strtrim(dt), 'oc-instantaneous'))
        kind = 'OC';
        return;
    end
end
if ~isempty(strfind(id, '51N'))
    kind = 'EF';
else
    kind = 'OC';
end
end

function r = buildRow(T40, dev, id, el, zone, legCol, zoneTag, kind)
r = emptyRow();
r.device_id = id;
r.element = el;
r.zone_locs = zoneTag;
if isempty(zone)
    r.branch_tag = 'NOT-APPLICABLE-no-zone-mapping-for-device';
    r.n_zone = 0;
    r.n_used = 0;
    r.reason = sprintf(['zone-not-mapped:%s-has-no-zone-relevant-faults;' ...
        'no-pickup-no-margin-no-verdict-beyond-NOT-DETERMINABLE'], id);
    return;
end
zhit = ismember(T40.fault_location, zone);
r.n_zone = sum(zhit);
if strcmp(el, 'negseq')
    r.branch_tag = 'NOT-APPLICABLE-branch-I2-unavailable-in-T40';
    r.n_used = 0;
    r.reason = sprintf(['negseq-branch-NOT-DETERMINABLE:branch-I2-unavailable-in-T40-' ...
        'production-CSVs;fault-point-sequence-current-is-a-total-never-derived-' ...
        'per-branch-current-doctrine;zone-%s-rows-%d-untouched'], zoneTag, r.n_zone);
    return;
end
if strcmp(el, 'phase') && ~strcmp(kind, 'OC')
    r.branch_tag = 'NOT-APPLICABLE-phase-element-on-EF-device';
    r.n_used = 0;
    r.reason = sprintf(['phase-element-not-applicable:%s-is-earth-fault-device;' ...
        'phase-coverage-NOT-DETERMINABLE;zone-%s-rows-%d-untouched'], id, zoneTag, r.n_zone);
    return;
end
if strcmp(el, 'residual') && ~(strcmp(kind, 'EF') && strcmp(zoneTag, 'F1+F2'))
    r.branch_tag = 'NOT-APPLICABLE-branch-residual-unavailable-in-T40';
    r.n_used = 0;
    if strcmp(kind, 'EF')
        why = 'residual-branch-only-via-NER-series-leg-valid-in-GEN-zone-F1F2';
    else
        why = 'residual-element-not-applicable-to-phase-device';
    end
    r.reason = sprintf(['residual-NOT-DETERMINABLE:%s:%s;' ...
        'zone-%s-rows-%d-untouched'], id, why, zoneTag, r.n_zone);
    return;
end
if strcmp(el, 'phase')
    % |Ia|-representative types only (LL/LLG stored |Ia| is unfaulted-phase).
    typeOK = ismember(T40.fault_type, {'LLL', 'LG'});
    vals = abs(double(T40.(legCol))) * 1000;
    r.branch_tag = sprintf('%s-magnitude-via-%s-SOURCE-BACKED', shortTag(legCol), legCol);
    scopeNote = 'LL-LLG-excluded-unfaulted-phase-Ia-only-in-production-data';
elseif strcmp(el, 'residual')
    % GEN-zone 3I0 from the NER series leg (LG sensitivity scope; LLG observed-only).
    typeOK = strcmp(T40.fault_type, 'LG');
    vals = 3 * abs(double(T40.leg_NER_earth_kA)) * 1000;
    r.branch_tag = '3I0-from-leg_NER_earth_kA-x3-series-SOURCE-BACKED';
    scopeNote = 'LLG-observed-only-out-of-LG-sensitivity-scope';
else
    error('phase5b_mindetect:internal', 'unknown element %s.', el);
end
cand = zhit & typeOK & isfinite(vals);
r.n_used = sum(cand);
if r.n_used < 1
    r.reason = sprintf(['no-finite-branch-current:%s-%s-zone-%s-candidate-rows-0;' ...
        'scope-%s;NOT-DETERMINABLE'], id, el, zoneTag, scopeNote);
    return;
end
[mn, ix] = min(vals(cand));
rows = find(cand);
r.min_branch_A = mn;
r.min_loc = char(T40.fault_location(rows(ix)));
r.min_type = char(T40.fault_type(rows(ix)));
r.min_case = char(T40.caseID(rows(ix)));
nDrop = r.n_zone - r.n_used;
% Observed-but-out-of-scope LLG residual (transparency, never a verdict input).
extra = '';
if strcmp(el, 'residual')
    llg = zhit & strcmp(T40.fault_type, 'LLG') & isfinite(vals);
    if any(llg)
        extra = sprintf(';LLG-observed-3I0-min-%.3fA-out-of-scope-flagged-limitation', ...
            min(vals(llg)));
    end
end
% C4 pickup for the computed branch minimum (settings are load-based).
Iload = loadAnchor(id);
try
    P = phase5b_pickup(dev, Iload, mn);
catch ME
    r.pickup_A = NaN;
    r.pickup_src = 'NOT-DETERMINABLE-pickup-engine-refused';
    r.margin = NaN;
    r.reason = sprintf(['pickup-refused:%s-%s-min-%.3fA-at-%s-%s-%s;' ...
        'engine-%s;NOT-DETERMINABLE'], id, el, mn, r.min_loc, r.min_type, ...
        r.min_case, ME.identifier);
    return;
end
r.pickup_A = P.setting;
r.pickup_src = P.source;
r.margin = mn / P.setting;
r.determinable = true;
if r.margin >= 1
    r.verdict = 'DETECT';
else
    r.verdict = 'BLIND-SPOT-HONEST';
end
r.reason = sprintf(['min-over-%d-of-%d-zone-rows(scope-%s%s);' ...
    'branch-%s=%.3fA-at-%s-%s-%s-vs-pickup-%.3fA(margin-%.4f);verdict-%s'], ...
    r.n_used, r.n_zone, scopeNote, extra, r.branch_tag, mn, ...
    r.min_loc, r.min_type, r.min_case, P.setting, r.margin, r.verdict);
end

function t = shortTag(legCol)
%SHORTTAG  Through-current tag label for a T40 branch column (rename contract: branch-through-current).
switch legCol
    case 'leg_GEN_kA'
        t = 'GEN_Q-branch-through-current';
    case 'leg_GSUT_HV_kA'
        t = 'GSUT_HV-branch-through-current';
    case 'leg_LINE_total_kA'
        t = 'LINE_Q9-through-convention-branch-through-current';
    otherwise
        t = 'branch-through-current';
end
end

function a = loadAnchor(id)
%LOADANCHOR  Locked study load anchors (PRIMARY A) for the C4 pickup rules.
if strncmp(id, 'GEN-51N', 7)
    a = 0;  % fixed 5 A retained sensitive case (load-independent)
elseif strncmp(id, 'GEN-', 4)
    a = 14309;  % generator max operating current (ledger GEN-Imax-14309)
elseif strncmp(id, 'GSUT-HV', 7)
    a = 870.772573866956;  % GSUT_HV flow anchor (rule takes max with rated 1150 A)
elseif strncmp(id, 'GIS-Q0', 6)
    a = 869.956651959241;  % LINE_Q9 flow anchor from ct_data FL_anchor
else
    a = 0;
end
end

function B = phase5b_branch_phasors(T40)
%PHASE5B_BRANCH_PHASORS  Identity-gated branch-phasor recompute for LL/LLG B/C (Phase-5b Task C6b).
%   B = PHASE5B_BRANCH_PHASORS(T40) where T40 is the phase5_import 40-row
%   backbone. The frozen Phase-4 writer stores leg magnitudes as |Ia| ONLY
%   (phase4_handoff legRow: row(k) = abs(C.legs.(tags{k}).Ia)*Ibase), while
%   LL/LLG faults involve phases B/C -- so Ia evidence is wrong-phase for
%   B/C overcurrent elements. The leg phasors (Ia/Ib/Ic complex per leg)
%   exist inside phase4_contrib but were never written to CSV. This module
%   recomputes them.
%
%   For each (caseID,location,fault_type) backbone row, the module calls the
%   FROZEN phase4_contrib read-only (never modified):
%     C = phase4_contrib(caseID, 'P', 15, loc, type, 'Ikpp', [], 'bolted')
%   Backbone opts discovery (from run_phase4_matrix legDesc plus
%   run_phase4_production merge order, modifying nothing):
%     - ds 'P', XoR_P 15: legDesc base defaults (base = LF360_GAT_OUT,
%       GAT-IN = LF360_GAT_IN; both keep ds P, XoR 15; each OFAT leg varies
%       exactly one factor, so backbone rows are base-opts rows).
%     - stage 'Ikpp', t_break []: backbone segment covers {Ikpp,ip} and the
%       import keeps stage Ikpp; per-leg ip has no table
%       (phase4_contrib:ipNoTable), so Ikpp is the only leg-bearing stage;
%       t_break is ignored for non-Ib stages (handoff passes [] too).
%     - ZfMode 'bolted': legDesc base ZfMode (Zf_ohm 0).
%     - m = 0.5: phase4_solve default (matrix F4 subset guard) matching the
%       import F4-primary-m==0.5 guard.
%     - caseID/loc/type come from the T40 row itself (F1/F2 labels kept
%       distinct though values are identical).
%
%   Magnitudes are in amperes at fault voltage level with the SAME Ibase
%   convention as the frozen handoff writer: Ibase = 100/(sqrt(3)*Vlevel) kA
%   with Vlevel from loc (F1/F2 22 kV, F3/F4/F5 230 kV); A = |Ipu|*Ibase*1000.
%   (The handoff applies the single fault-level Ibase to every leg of the
%   row; this module does exactly the same, which is what makes the identity
%   gate below satisfiable. Per-leg own-voltage bases are NOT used.)
%
%   IDENTITY GATE (binding): recomputed |Ia| per (row,leg) must equal the
%   production contributions CSV leg value (results/phase4_fault/production/
%   phase4_contributions.csv, first stable row per (caseID,location,
%   fault_type) among stage Ikpp & m==0.5 -- the same backbone-first
%   dedup the phase5_import backbone relies on) within 1e-6 relative
%   (rel = |rec-ref|/max(|ref|,1e-30), ref in kA). ANY failure -- numeric
%   mismatch, missing production reference row, missing leg column, a finite
%   production leg with no recomputed counterpart (omission), or a mismatch
%   against the T40-carried import leg value (auxiliary cross-check under the
%   same gate: T40 legs ARE the import join of the CSV values, pinned by the
%   C5 branch audit, so both references must agree) -- errors
%   error('phase5b_branch_phasors:identity', 'BLOCKED ...') listing the first
%   failing rows. Loudly BLOCKED, no fallback values, no tolerance widening.
%   Downstream C8 then uses NOT-DETERMINABLE for LL/LLG B/C (acceptable
%   fallback).
%
%   Faulted-phase branch magnitude per type (B/C evidence for C8):
%     LLL -> max(|Ia|,|Ib|,|Ic|), phase_basis 'maxABC';
%     LG  -> |Ia| (A-phase faulted), phase_basis 'Ia';
%     LL, LLG -> max(|Ib|,|Ic|) (B/C faulted), phase_basis 'maxBC'.
%
%   Output B is a table with locked columns (this order):
%     caseID, location, fault_type, leg, Ia_A, Ib_A, Ic_A,
%     Ibranch_faulted_A, phase_basis.
%   One row per (backbone row x present contrib leg). leg names are the raw
%   phase4_contrib field names (GEN, GSUT_LV, GSUT_HV, UAT, GAT_HV, GAT_LV,
%   LINE_total, LINE_B1, LINE_B2, GRID, NER_earth); absent legs (GAT iff OUT,
%   NER_earth unless LG/LLG, LINE_B1/B2 unless F4) are omitted, never
%   zero-filled. Subset inputs (fewer rows, same columns) are accepted for
%   testing; production use is the full 40-row backbone.
%
%   All errors are 'phase5b'-prefixed. No existing file is modified; no
%   re-solve of Phase-4 defaults is altered (phase4_contrib is called, never
%   edited).
if nargin ~= 1
    error('phase5b_branch_phasors:args', ...
        'usage: B = phase5b_branch_phasors(T40).');
end
if ~istable(T40) || height(T40) < 1
    error('phase5b_branch_phasors:schema', ...
        'T40 must be a non-empty table (phase5_import backbone).');
end
if any(strcmp(T40.Properties.VariableNames, 'fault_location'))
    locCol = 'fault_location';
elseif any(strcmp(T40.Properties.VariableNames, 'location'))
    locCol = 'location';
else
    error('phase5b_branch_phasors:schema', ...
        'T40 missing location column (fault_location/location).');
end
need = {'fault_type', 'caseID'};
for k = 1:numel(need)
    if ~any(strcmp(T40.Properties.VariableNames, need{k}))
        error('phase5b_branch_phasors:schema', ...
            'T40 missing required column %s.', need{k});
    end
end
n = height(T40);
locs = cell(n, 1);
types = cell(n, 1);
cases = cell(n, 1);
for i = 1:n
    lo = T40.(locCol){i};
    ty = T40.fault_type{i};
    ca = T40.caseID{i};
    if isstring(lo) && isscalar(lo), lo = char(lo); end
    if isstring(ty) && isscalar(ty), ty = char(ty); end
    if isstring(ca) && isscalar(ca), ca = char(ca); end
    if ~ischar(lo) || ~any(strcmp(lo, {'F1', 'F2', 'F3', 'F4', 'F5'}))
        error('phase5b_branch_phasors:schema', ...
            'T40 row %d: unknown location (use F1/F2/F3/F4/F5).', i);
    end
    if ~ischar(ty) || ~any(strcmp(ty, {'LLL', 'LG', 'LL', 'LLG'}))
        error('phase5b_branch_phasors:schema', ...
            'T40 row %d: unknown fault_type (use LLL/LG/LL/LLG).', i);
    end
    if ~ischar(ca) || isempty(strtrim(ca))
        error('phase5b_branch_phasors:schema', ...
            'T40 row %d: caseID must be non-empty char.', i);
    end
    locs{i} = lo;
    types{i} = ty;
    cases{i} = strtrim(ca);
end

% --- Production contributions reference (read-only; backbone-first dedup) ---
root = ashuganj_root();
Fc = fullfile(root, 'results', 'phase4_fault', 'production', ...
    'phase4_contributions.csv');
if exist(Fc, 'file') ~= 2
    error('phase5b_branch_phasors:identity', ...
        ['BLOCKED: production contributions CSV missing: ' Fc]);
end
K = readtable(Fc);
Kb = K(strcmp(K.stage, 'Ikpp') & K.m == 0.5, :);
kkeys = strcat(Kb.caseID, '|', Kb.location, '|', Kb.fault_type);
[~, ika] = unique(kkeys, 'stable');
Kb1 = Kb(ika, :);

% --- Recompute + gate ---
outCase = cell(0, 1);
outLoc = cell(0, 1);
outType = cell(0, 1);
outLeg = cell(0, 1);
outIa = zeros(0, 1);
outIb = zeros(0, 1);
outIc = zeros(0, 1);
outBr = zeros(0, 1);
outBasis = cell(0, 1);
fail = {};
for i = 1:n
    lo = locs{i};
    ty = types{i};
    ca = cases{i};
    if any(strcmp(lo, {'F1', 'F2'}))
        Vlevel = 22;
    else
        Vlevel = 230;
    end
    Ibase = 100 / (sqrt(3) * Vlevel);  % kA, handoff convention
    C = phase4_contrib(ca, 'P', 15, lo, ty, 'Ikpp', [], 'bolted');
    hit = strcmp(Kb1.caseID, ca) & strcmp(Kb1.location, lo) ...
        & strcmp(Kb1.fault_type, ty);
    if sum(hit) ~= 1
        fail{end+1} = sprintf('row %d %s %s %s: %d production reference rows (want 1)', ...
            i, ca, lo, ty, sum(hit)); %#ok<AGROW>
        continue;
    end
    ref = Kb1(find(hit, 1, 'first'), :);
    legs = fieldnames(C.legs);
    emitted = cell(0, 1);
    for q = 1:numel(legs)
        leg = legs{q};
        L = C.legs.(leg);
        aA = abs(L.Ia) * Ibase * 1000;
        bA = abs(L.Ib) * Ibase * 1000;
        cA = abs(L.Ic) * Ibase * 1000;
        switch ty
            case 'LLL'
                br = max([aA, bA, cA]);
                basis = 'maxABC';
            case 'LG'
                br = aA;
                basis = 'Ia';
            otherwise  % LL, LLG: B/C faulted
                br = max(bA, cA);
                basis = 'maxBC';
        end
        col = ['leg_' leg '_kA'];
        if ~any(strcmp(ref.Properties.VariableNames, col))
            fail{end+1} = sprintf('row %d %s %s %s leg %s: no production leg column %s', ...
                i, ca, lo, ty, leg, col); %#ok<AGROW>
            continue;
        end
        rv = ref.(col);
        if ~isfinite(rv)
            fail{end+1} = sprintf('row %d %s %s %s leg %s: production leg value not finite', ...
                i, ca, lo, ty, leg); %#ok<AGROW>
            continue;
        end
        recK = aA / 1000;
        if abs(recK - rv) / max(abs(rv), 1e-30) > 1e-6
            fail{end+1} = sprintf(['row %d %s %s %s leg %s: recomputed |Ia| %.12g kA vs ' ...
                'production %.12g kA (rel %.3g > 1e-6)'], ...
                i, ca, lo, ty, leg, recK, rv, ...
                abs(recK - rv) / max(abs(rv), 1e-30)); %#ok<AGROW>
            continue;
        end
        if any(strcmp(T40.Properties.VariableNames, col))
            tv = T40.(col)(i);  % leg columns are numeric (phase5_import join)
            if isfinite(tv) && abs(recK - tv) / max(abs(tv), 1e-30) > 1e-6
                fail{end+1} = sprintf(['row %d %s %s %s leg %s: recomputed |Ia| %.12g kA vs ' ...
                    'T40-carried %.12g kA (rel %.3g > 1e-6)'], ...
                    i, ca, lo, ty, leg, recK, tv, ...
                    abs(recK - tv) / max(abs(tv), 1e-30)); %#ok<AGROW>
                continue;
            end
        end
        outCase{end+1, 1} = ca; %#ok<AGROW>
        outLoc{end+1, 1} = lo; %#ok<AGROW>
        outType{end+1, 1} = ty; %#ok<AGROW>
        outLeg{end+1, 1} = leg; %#ok<AGROW>
        outIa(end+1, 1) = aA; %#ok<AGROW>
        outIb(end+1, 1) = bA; %#ok<AGROW>
        outIc(end+1, 1) = cA; %#ok<AGROW>
        outBr(end+1, 1) = br; %#ok<AGROW>
        outBasis{end+1, 1} = basis; %#ok<AGROW>
        emitted{end+1, 1} = leg; %#ok<AGROW>
    end
    % Omission guard: every finite production leg must have been emitted.
    vn = ref.Properties.VariableNames;
    for q = 1:numel(vn)
        tok = regexp(char(vn{q}), '^leg_(.+)_kA$', 'tokens', 'once');
        if isempty(tok)
            continue;
        end
        if isfinite(ref.(vn{q})) && ~any(strcmp(emitted, tok{1}))
            fail{end+1} = sprintf('row %d %s %s %s leg %s: finite production leg omitted', ...
                i, ca, lo, ty, tok{1}); %#ok<AGROW>
        end
    end
end
if ~isempty(fail)
    nshow = min(numel(fail), 10);
    error('phase5b_branch_phasors:identity', ...
        ['BLOCKED: identity gate failed on %d (row,leg) checks (tolerance 1e-6 relative, ' ...
         'no fallback values). First %d: %s'], ...
        numel(fail), nshow, strjoin(fail(1:nshow), ' | '));
end

B = table(outCase, outLoc, outType, outLeg, outIa, outIb, outIc, outBr, outBasis, ...
    'VariableNames', {'caseID', 'location', 'fault_type', 'leg', 'Ia_A', ...
    'Ib_A', 'Ic_A', 'Ibranch_faulted_A', 'phase_basis'});
end

