T = T.chk(islogical(Pg.use_phase5_time) && isscalar(Pg.use_phase5_time) && Pg.use_phase5_time, 'C4 GEN-51-SI use_phase5_time true (inverse allowed)');
T = T.chk(abs(Pg.setting_sec_A - Pg.setting / 15000) / Pg.setting_sec_A < 1e-12, 'C4 GEN-51-SI secondary Is/15000');
T = T.chk(abs(Pg.setting_sec_A - 1.14472) / 1.14472 < 1e-9, 'C4 GEN-51-SI secondary 1.14472 A');
T = T.chk(~isempty(strfind(Pg.basis, 'max-operating-current')) && ~isempty(strfind(Pg.basis, 'Imax-14309A')), 'C4 GEN basis documents max-operating-current Imax-14309A');
T = T.chk(~isempty(strfind(Pg.source, '17171A')) || ~isempty(strfind(Pg.validation, '17171A')), 'C4 GEN convergence with Siemens 17171A noted');
T = T.chk(abs(Pg.setting - 17171) / 17171 < 0.005, 'C4 GEN convergence band vs Siemens baseline <0.5%');
T = T.chk(~strcmp(Pg.curve, P.curve), 'C4 GEN study characteristic differs from DT baseline');
T = T.chk(strcmp(char(Pg.unit), 'A-primary') && strcmp(Pg.assumption_class, 'PRIMARY'), 'C4 GEN unit A-primary, class PRIMARY');
ga = g;
ga.device_id = 'GEN-51-SI';
Pa = phase5b_pickup(ga, FL_GENQ_A, IMIN_PHASE_A);
T = T.chk(abs(Pa.setting - Pg.setting) / Pg.setting < 1e-12, 'C4 GEN-51-SI alias same setting as GEN-51');
tgen = phase5_time(2 * Pg.setting_sec_A, Pg.setting_sec_A, Pg.tms, Pg.curve);
T = T.chk(isfinite(tgen) && tgen > 0 && tgen < 10, 'C4 phase5_time accepts study SI row (finite time)');
gs = R.devices(strcmp(ids, 'GSUT-HV-51'));
ILOAD_GSUT_A = 870.772573866956;
Ps = phase5b_pickup(gs, ILOAD_GSUT_A, IMIN_PHASE_A);
T = T.chk(abs(Ps.setting - 1380) / 1380 < 1e-9, 'C4 GSUT-HV-51 setting 1.2xmax(1150,870.7726)=1380 A');
T = T.chk(abs(Ps.tms - 0.20) < 1e-12, 'C4 GSUT-HV-51 TMS 0.20');
T = T.chk(abs(Ps.setting_sec_A - 1380 / 1600) / (1380 / 1600) < 1e-12, 'C4 GSUT secondary 1380/1600=0.8625 A');
T = T.chk(~isempty(strfind(Ps.basis, 'max(')) && ~isempty(strfind(Ps.source, '1600/1')), 'C4 GSUT basis max() via 1600/1');
gq = R.devices(strcmp(ids, 'GIS-Q0-51'));
ILOAD_Q0_A = 869.956651959241;
Pq = phase5b_pickup(gq, ILOAD_Q0_A, IMIN_PHASE_A);
T = T.chk(abs(Pq.setting - 1.2 * ILOAD_Q0_A) / Pq.setting < 1e-12, 'C4 GIS-Q0-51 setting 1.2x869.956652');
T = T.chk(abs(Pq.tms - 0.20) < 1e-12, 'C4 GIS-Q0-51 TMS 0.20');
T = T.chk(abs(Pq.setting_sec_A - Pq.setting / 1600) / Pq.setting_sec_A < 1e-12, 'C4 GIS secondary Is/1600');
ge = R.devices(strcmp(ids, 'GEN-51N'));
IMIN_EF_A = 7.27200442799167;
Pe = phase5b_pickup(ge, 0, IMIN_EF_A);
T = T.chk(abs(Pe.setting - 5) < 1e-12, 'C4 GEN-51N-SI-STUDY setting 5 A retained');
T = T.chk(strcmp(Pe.assumption_class, 'SENSITIVITY'), 'C4 EF scope SENSITIVITY');
T = T.chk(abs(Pe.tms - 0.15) < 1e-12 && abs(Pe.ef_tms - 0.15) < 1e-12, 'C4 EF TMS 0.15 per master S21');
T = T.chk(abs(Pe.setting_sec_A - 5 / 15000) / (5 / 15000) < 1e-9, 'C4 EF secondary 5/15000');
ge2 = ge;
ge2.device_id = 'GEN-51N-SI-STUDY';
Pe2 = phase5b_pickup(ge2, 0, IMIN_EF_A);
T = T.chk(abs(Pe2.setting - 5) < 1e-12, 'C4 GEN-51N-SI-STUDY alias 5 A');
tef = phase5_time(2 * Pe.setting_sec_A, Pe.setting_sec_A, Pe.tms, Pe.curve);
T = T.chk(isfinite(tef) && tef > 0, 'C4 phase5_time accepts study EF SI row (finite time)');
q50 = R.devices(strcmp(ids, 'GIS-Q0-50'));
try
    phase5b_pickup(q50, ILOAD_Q0_A, IMIN_PHASE_A);
    T = T.chk(false, 'C4 GIS-Q0-50 stays DISABLED');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_pickup:disabled'), 'C4 GIS-Q0-50 DISABLED (TMS never enables; phase5b_pickup:disabled)');
end
ln = R.devices(strcmp(ids, 'LINE-21-note'));
try
    phase5b_pickup(ln, 0, IMIN_PHASE_A);
    T = T.chk(false, 'C4 LINE-21-note has no settings');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'C4 note/boundary error phase5b-prefixed (no stub)');
end
% --- Errors phase5b-prefixed ---
try
    phase5b_pickup(dev, -1, IMIN_PHASE_A);
    T = T.chk(false, 'negative Iload errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'Iload error phase5b-prefixed');
end
try
    phase5b_pickup(struct('device_id', ''), FL_GENQ_A, IMIN_PHASE_A);
    T = T.chk(false, 'empty device_id errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'device error phase5b-prefixed');
end
[np, nf] = T.done();
end

