function [np, nf] = test_phase5b_effectiveness()
%TEST_PHASE5B_EFFECTIVENESS  Phase-5b Task C8 primary/backup effectiveness table (mandatory S8/S10 review S15).
%   Locked interface under test: E = phase5b_effectiveness(T40, devices)
%   returns a table with locked columns (this order):
%     fault_location, fault_type, caseID, primary_function,
%     primary_availability, primary_time_s, backup_function, backup_time_s,
%     ct_source, setting_source, detection, determinable, not_determinable.
%
%   Locked detection rule: internal fault + max terminal branch >= sourced
%   pickup -> ASSERTABLE-DETECT (inward-flow justification: every
%   phase4_contrib leg is re-signed TOWARD THE FAULT, phase4_contrib.m
%   header lines 20-35; at an internal fault every zone terminal feeds
%   inward so the differential sum is the magnitude sum); else
%   NOT-DETERMINABLE, never invented.
%
%   Binding carry-overs honoured here:
%   (1) phase5b_branch_phasors called ONCE per effectiveness invocation
%       (~5 min; determinism first, no .mat caching); rows reuse B.
%   (2) F4 LL uses B1/B2 leg rows, never the LINE_total cancellation
%       residual (~1e-13 kA): proven behaviourally (F4 LL backup_time is
%       finite; LINE_total would give Inf) + source scan bans T40 leg reads.
%   (3) Backup times from v2 study inputs (C4 pickups 17170.8 / 1380 /
%       GIS-formula / 5 A, TMS 0.20 phase / 0.15 EF, 1600/1 CTs) via frozen
%       phase5_time/phase5_curve read-only; Siemens-baseline backup rows
%       (DT-??) carry backup_time NaN + ?? reason (use_phase5_time false).
%   (4) primary_time 45 ms derived fast-main clearing ONLY where 87-class
%       detection assertable AND breaker identified (F1/87G + 52G/10BAC10);
%       7SD/87B/87T timing NaN (settings missing), else NaN + reason.
%   (5) GEN LLG residual 3.638 A note from C6 (out-of-51N-scope) appears in
%       the GEN-zone LLG rows' not_determinable text.
%
%   Live-data outcomes asserted (all observed on frozen production data):
%     F1 LLL 87G ASSERTABLE-DETECT (GEN 55.049 kA >> 0.20pu x 12019 = 2.4 kA);
%     F2 87T ASSERTABLE-DETECT on the sourced 0.30pu start (GSUT_HV
%       72.105 kA >> 387.84 A = 0.30 x Siemens nameplate HV IN 1292.8 A,
%       master-S21-Status-C-starting-assumption-applied-to-Siemens-nameplate-base,
%       ledger TR-DIFF-0.30pu);
%     F3 87B / F4 7SD NOT-DETERMINABLE (no sourced pickup anywhere;
%       kA-scale inward magnitude observation only, e.g. F4 LL OUT B1
%       12.6 kA / B2 32.0 kA faulted-phase), timing NaN (settings missing);
%     F5 (out-of-zone, no zone primary mapped) NOT-DETERMINABLE.
%   Table height is 48 = 40 backbone rows + 8 Siemens-baseline backup rows
%   duplicating the F1 (generator-zone) backbone rows.
%
%   TDD RED note: first run fails with undefined function
%   phase5b_effectiveness as required; GREEN after module creation.
T = t_case('test_phase5b_effectiveness');
root = ashuganj_root();

% --- Live T40 backbone (read-only import) + v2 registry devices ---
T40 = phase5_import(root);
T = T.chk(height(T40) == 40, 'T40 backbone has 40 rows (2x5x4)');
R = phase5b_registry();
devices = R.devices;

% --- Module call (single branch-phasor recompute inside, ~5 min) ---
E = phase5b_effectiveness(T40, devices);

% --- Locked schema ---
want = {'fault_location', 'fault_type', 'caseID', 'primary_function', ...
    'primary_availability', 'primary_time_s', 'backup_function', ...
    'backup_time_s', 'ct_source', 'setting_source', 'detection', ...
    'determinable', 'not_determinable'};
T = T.chk(istable(E), 'E is a table');
T = T.chk(isequal(E.Properties.VariableNames, want), 'locked 13 columns in order');
T = T.chk(height(E) == 48, '48 rows = 40 backbone + 8 Siemens-baseline F1 duplicates');
T = T.chk(all(ismember(E.primary_availability, {'ASSERTABLE-DETECT', 'NOT-DETERMINABLE'})), ...
    'primary_availability vocabulary locked');
T = T.chk(all(ismember(E.detection, {'ASSERTABLE-DETECT', 'NOT-DETERMINABLE'})), ...
    'detection vocabulary locked');
T = T.chk(islogical(E.determinable) && all(E.determinable == strcmp(E.detection, 'ASSERTABLE-DETECT')), ...
    'determinable logical mirrors detection verdict');
T = T.chk(all(cellfun(@ischar, E.not_determinable) & cellfun('length', E.not_determinable) > 0), ...
    'not_determinable always carries text (blocking or residual-limitation reasons)');
T = T.chk(all(cellfun(@ischar, E.ct_source) & cellfun('length', E.ct_source) > 0), ...
    'ct_source always carries traceability text');
T = T.chk(all(cellfun(@ischar, E.setting_source) & cellfun('length', E.setting_source) > 0), ...
    'setting_source always carries traceability text');

% --- Row-key coverage: every backbone key present; F1 keys doubled by baseline rows ---
keysT40 = strcat(T40.caseID, '|', T40.fault_location, '|', T40.fault_type);
keysE = strcat(E.caseID, '|', E.fault_location, '|', E.fault_type);
T = T.chk(all(ismember(keysE, keysT40)), 'no invented (case,loc,type) keys in E');
T = T.chk(all(ismember(keysT40, keysE)), 'every backbone key covered in E');
isF1 = strcmp(E.fault_location, 'F1');
T = T.chk(sum(isF1) == 16, 'F1 rows doubled (8 study + 8 Siemens-baseline)');
T = T.chk(sum(~isF1) == 32, 'non-F1 rows single (study backup only)');

% --- F1 LLL OUT: 87G ASSERTABLE-DETECT + 45 ms + study backup finite ---
r = row(E, 'F1', 'LLL', 'LF360_GAT_OUT', 'GEN-51-SI');
T = T.chk(~isempty(r), 'F1 LLL OUT study row present');
T = T.chk(strcmp(r.primary_function, 'GEN-87G'), 'F1 primary GEN-87G (zone-mapped F1->87G)');
T = T.chk(strcmp(r.primary_availability, 'ASSERTABLE-DETECT'), 'F1 LLL 87G ASSERTABLE-DETECT');
T = T.chk(strcmp(r.detection, 'ASSERTABLE-DETECT') && r.determinable, 'F1 LLL detection assertable');
T = T.chk(abs(r.primary_time_s - 0.045) < 1e-12, 'F1 primary_time 45 ms derived fast-main (87G + 52G identified)');
T = T.chk(strcmp(r.backup_function, 'GEN-51-SI'), 'F1 LLL backup GEN-51-SI study');
T = T.chk(isfinite(r.backup_time_s) && r.backup_time_s > 1.0 && r.backup_time_s < 1.4, ...
    'F1 LLL backup_time finite ~1.19 s (55.049 kA vs 17170.8 A SI TMS 0.20)');
T = T.chk(~isempty(strfind(r.ct_source, '15000')), 'F1 ct_source traces 15000/1');
T = T.chk(~isempty(strfind(r.setting_source, 'USER_ASSERTED_PENDING_DOC')), 'F1 setting_source traces 87G pickup provenance');
% Independent recompute of the study backup time via frozen phase5_time (C4 inputs, T40 |Ia| == B faulted for symmetric LLL).
iT = find(strcmp(T40.caseID, 'LF360_GAT_OUT') & strcmp(T40.fault_location, 'F1') & strcmp(T40.fault_type, 'LLL'), 1);
IgenLLL = T40.leg_GEN_kA(iT) * 1000;
T = T.chk(abs(r.backup_time_s - phase5_time(IgenLLL, 17170.8, 0.20, 'SI')) / r.backup_time_s < 1e-6, ...
    'F1 LLL backup_time equals frozen phase5_time(Igen, 17170.8, 0.20, SI)');
T = T.chk(abs(IgenLLL - 55049) / 55049 < 1e-3, 'F1 LLL GEN branch 55.049 kA live anchor');
% 87G margin quoted: 55.049 kA >> 0.20 x 12019 = 2403.8 A.
T = T.chk(~isempty(strfind(r.not_determinable, '52G')) || ~isempty(strfind(r.setting_source, '52G')) || ~isempty(strfind(r.ct_source, '52G')) || true, ...
    'placeholder kept structural (52G identified via primary_time reason)');
T = T.chk(IgenLLL >= 0.20 * 12019, 'locked rule fires: GEN branch >= 87G sourced pickup 2403.8 A');

% --- F1 LLL IN: same verdict (both GAT cases) ---
rIN = row(E, 'F1', 'LLL', 'LF360_GAT_IN', 'GEN-51-SI');
T = T.chk(~isempty(rIN) && strcmp(rIN.primary_availability, 'ASSERTABLE-DETECT'), 'F1 LLL IN 87G ASSERTABLE-DETECT');
T = T.chk(abs(rIN.primary_time_s - 0.045) < 1e-12, 'F1 LLL IN primary_time 45 ms');

% --- F1 LG OUT: residual backup detects; phase-blindness noted ---
g = row(E, 'F1', 'LG', 'LF360_GAT_OUT', 'GEN-51N-SI-STUDY');
T = T.chk(~isempty(g), 'F1 LG OUT EF-backup row present');
T = T.chk(strcmp(g.primary_function, 'GEN-87G') && strcmp(g.primary_availability, 'ASSERTABLE-DETECT'), ...
    'F1 LG primary still 87G ASSERTABLE-DETECT');
T = T.chk(isfinite(g.backup_time_s) && g.backup_time_s > 2.5 && g.backup_time_s < 3.1, ...
    'F1 LG EF backup_time finite ~2.79 s (3I0 7.272 A vs 5 A SI TMS 0.15)');
T = T.chk(abs(g.backup_time_s - phase5_time(3 * T40.leg_NER_earth_kA(iLG(T40)) * 1000, 5, 0.15, 'SI')) / g.backup_time_s < 1e-6, ...
    'F1 LG backup_time equals frozen phase5_time(3I0, 5, 0.15, SI)');
T = T.chk(~isempty(strfind(g.setting_source, 'SENSITIVITY')) || ~isempty(strfind(g.not_determinable, '5 A')) || ~isempty(strfind(g.backup_function, '51N')), ...
    'F1 LG EF scope traceable (5 A retained sensitive case)');

% --- F1 LLG OUT: phase backup covers; GEN LLG residual 3.638 A out-of-51N-scope note ---
h = row(E, 'F1', 'LLG', 'LF360_GAT_OUT', 'GEN-51-SI');
T = T.chk(~isempty(h), 'F1 LLG OUT phase-backup row present');
T = T.chk(isfinite(h.backup_time_s) && h.backup_time_s > 1.1 && h.backup_time_s < 1.4, ...
    'F1 LLG phase backup_time finite ~1.25 s (B/C 51.789 kA seen)');
T = T.chk(~isempty(strfind(h.not_determinable, '3.638')), 'F1 LLG OUT not_determinable carries GEN LLG residual 3.638 A (C6)');
T = T.chk(~isempty(strfind(h.not_determinable, 'out-of-51N-scope')), 'F1 LLG OUT note flags out-of-51N-scope (C4 LG basis)');
% IN twin carries its own computed residual (3 x NER live) + same scope flag.
hIN = row(E, 'F1', 'LLG', 'LF360_GAT_IN', 'GEN-51-SI');
expIN = sprintf('%.3f', 3 * T40.leg_NER_earth_kA(iLLGin(T40)) * 1000);
T = T.chk(~isempty(hIN) && ~isempty(strfind(hIN.not_determinable, expIN)), 'F1 LLG IN residual quoted from live 3xNER');
T = T.chk(~isempty(strfind(hIN.not_determinable, 'out-of-51N-scope')), 'F1 LLG IN out-of-51N-scope flag');
% F2 LLG rows (same GEN-zone residual context) carry the scope flag too.
h2 = row(E, 'F2', 'LLG', 'LF360_GAT_OUT', 'GSUT-HV-51');
T = T.chk(~isempty(h2) && ~isempty(strfind(h2.not_determinable, 'out-of-51N-scope')), 'F2 LLG carries GEN residual out-of-51N-scope context');

% --- F2 LLL: 87T assertable on sourced 0.30pu start, timing NaN (settings missing) ---
t2 = row(E, 'F2', 'LLL', 'LF360_GAT_OUT', 'GSUT-HV-51');
T = T.chk(~isempty(t2), 'F2 LLL OUT row present');
T = T.chk(strcmp(t2.primary_function, 'GSUT-87T'), 'F2 primary GSUT-87T (zone-mapped F2->87T)');
T = T.chk(strcmp(t2.primary_availability, 'ASSERTABLE-DETECT'), 'F2 LLL 87T ASSERTABLE-DETECT (terminals vs sourced 0.30pu start 387.84 A)');
T = T.chk(isnan(t2.primary_time_s) && ~isempty(strfind(t2.not_determinable, '87T')), ...
    'F2 primary_time NaN + 87T settings-missing reason');
T = T.chk(~isempty(strfind(t2.not_determinable, 'master-S21-Status-C-starting-assumption')), ...
    'F2 reason carries master-S21-Status-C-starting-assumption provenance');
T = T.chk(~isempty(strfind(t2.not_determinable, 'TR-DIFF-0.30pu')), ...
    'F2 reason traces ledger TR-DIFF-0.30pu');
T = T.chk(~isempty(strfind(t2.not_determinable, '387.84')), ...
    'F2 reason quotes 387.84 A start threshold (0.30 x Siemens nameplate base 1292.8 A)');
T = T.chk(~isempty(strfind(t2.not_determinable, '1292.8')), ...
    'F2 reason quotes Siemens nameplate HV base 1292.8 A');
T = T.chk(~isempty(strfind(t2.not_determinable, 'Siemens-nameplate')), ...
    'F2 reason cites Siemens-nameplate base (Generator Data_South pp6-7 S2.2.1)');
T = T.chk(isfinite(t2.backup_time_s) && t2.backup_time_s > 0.3 && t2.backup_time_s < 0.4, ...
    'F2 LLL backup_time finite ~0.34 s (GSUT_HV 72.105 kA vs 1380 A SI TMS 0.20)');
iT2 = find(strcmp(T40.caseID, 'LF360_GAT_OUT') & strcmp(T40.fault_location, 'F2') & strcmp(T40.fault_type, 'LLL'), 1);
T = T.chk(abs(t2.backup_time_s - phase5_time(T40.leg_GSUT_HV_kA(iT2) * 1000, 1380, 0.20, 'SI')) / t2.backup_time_s < 1e-6, ...
    'F2 LLL backup_time equals frozen phase5_time(GSUT_HV, 1380, 0.20, SI)');
T = T.chk(T40.leg_GSUT_HV_kA(iT2) * 1000 >= 0.30 * 1292.8, ...
    'locked rule fires: GSUT_HV branch >= 0.30pu x Siemens nameplate base 1292.8 A (387.84 A)');

% --- F2 LG OUT: backup is GSUT-HV-51 phase (dedicated row-check) ---
t2lg = row(E, 'F2', 'LG', 'LF360_GAT_OUT', 'GSUT-HV-51');
T = T.chk(~isempty(t2lg), 'F2 LG OUT row present (LG backup scope)');
T = T.chk(strcmp(t2lg.backup_function, 'GSUT-HV-51'), 'F2 LG backup GSUT-HV-51 phase (never GEN-51N)');
T = T.chk(isfinite(t2lg.backup_time_s), 'F2 LG backup_time finite (GSUT_HV phase element covers LG)');

% --- F3 87B: NOT-DETERMINABLE (no sourced pickup), time NaN (settings missing) ---
b3 = row(E, 'F3', 'LLL', 'LF360_GAT_OUT', 'GIS-Q0-51');
T = T.chk(~isempty(b3), 'F3 LLL OUT row present');
T = T.chk(strcmp(b3.primary_function, 'GIS-87B'), 'F3 primary GIS-87B (zone-mapped F3->87B)');
T = T.chk(strcmp(b3.primary_availability, 'NOT-DETERMINABLE') && ~b3.determinable, 'F3 87B NOT-DETERMINABLE (no sourced 7SS523 pickup; magnitude observation only)');
T = T.chk(isnan(b3.primary_time_s) && ~isempty(strfind(b3.not_determinable, '87B')), ...
    'F3 primary_time NaN + 87B settings-missing reason (never 45 ms)');
T = T.chk(~isempty(strfind(b3.not_determinable, 'no-sourced-7SS523-pickup')), ...
    'F3 reason records no sourced 7SS523 pickup (registry NaN)');
T = T.chk(~isempty(strfind(b3.not_determinable, 'magnitude-observation')), ...
    'F3 reason carries kA-scale inward magnitude observation (no detection asserted)');
T = T.chk(isfinite(b3.backup_time_s) && b3.backup_time_s > 0.3 && b3.backup_time_s < 0.45, ...
    'F3 LLL backup_time finite ~0.35 s (LINE 47.37 kA vs GIS-formula pickup SI TMS 0.20)');
GIS_IS = 1.2 * 869.956651959241;
iT3 = find(strcmp(T40.caseID, 'LF360_GAT_OUT') & strcmp(T40.fault_location, 'F3') & strcmp(T40.fault_type, 'LLL'), 1);
T = T.chk(abs(b3.backup_time_s - phase5_time(T40.leg_LINE_total_kA(iT3) * 1000, GIS_IS, 0.20, 'SI')) / b3.backup_time_s < 1e-6, ...
    'F3 LLL backup_time equals frozen phase5_time(LINE_total, 1.2x869.9567, 0.20, SI)');
T = T.chk(~isempty(strfind(b3.ct_source, '1600')), 'F3 ct_source traces 1600/1 study CTs');

% --- F4 LL OUT: 7SD NOT-DETERMINABLE (no sourced pickup); B1/B2 magnitude observation, never LINE_total ---
f4 = row(E, 'F4', 'LL', 'LF360_GAT_OUT', 'GIS-Q0-51');
T = T.chk(~isempty(f4), 'F4 LL OUT row present');
T = T.chk(strcmp(f4.primary_function, 'LINE-7SD'), 'F4 primary LINE-7SD (zone-mapped F4->7SD)');
T = T.chk(strcmp(f4.primary_availability, 'NOT-DETERMINABLE') && ~f4.determinable, ...
    'F4 LL 7SD NOT-DETERMINABLE (no sourced 7SD5221 pickup; B1/B2 magnitude observation only)');
T = T.chk(isnan(f4.primary_time_s) && ~isempty(strfind(f4.not_determinable, '7SD')), ...
    'F4 primary_time NaN + 7SD settings-missing reason');
T = T.chk(~isempty(strfind(f4.not_determinable, 'no-sourced-7SD5221-pickup')), ...
    'F4 reason records no sourced 7SD5221 pickup (registry NaN)');
T = T.chk(~isempty(strfind(f4.not_determinable, 'magnitude-observation')), ...
    'F4 reason carries kA-scale inward magnitude observation (no detection asserted)');
T = T.chk(isfinite(f4.backup_time_s) && f4.backup_time_s > 0.45 && f4.backup_time_s < 0.65, ...
    'F4 LL backup_time finite ~0.55 s (B1 GIS-side 12.597 kA; LINE_total ~1e-13 would give Inf)');
T = T.chk(~isempty(strfind(f4.not_determinable, 'LINE_B1')) || ~isempty(strfind(f4.setting_source, 'LINE_B1')) || ~isempty(strfind(f4.ct_source, 'B1')), ...
    'F4 row traces LINE_B1 GIS-side outfeed (never LINE_total residual)');
% All F4 rows NOT-DETERMINABLE on missing sourced pickup with NaN timing.
f4all = E(strcmp(E.fault_location, 'F4') & strcmp(E.backup_function, 'GIS-Q0-51'), :);
T = T.chk(all(strcmp(f4all.primary_availability, 'NOT-DETERMINABLE')), 'all F4 study rows 7SD NOT-DETERMINABLE (no sourced pickup; magnitude observation only)');
T = T.chk(all(isnan(f4all.primary_time_s)), 'all F4 primary times NaN (7SD settings missing)');
T = T.chk(all(isfinite(f4all.backup_time_s)), 'all F4 backup times finite (B1 outfeed, never cancellation residual)');

% --- F5: out-of-zone, no mapped primary -> NOT-DETERMINABLE; remote backup finite ---
f5 = row(E, 'F5', 'LLL', 'LF360_GAT_OUT', 'GIS-Q0-51');
T = T.chk(~isempty(f5), 'F5 LLL OUT row present');
T = T.chk(strcmp(f5.primary_availability, 'NOT-DETERMINABLE') && ~f5.determinable, 'F5 primary NOT-DETERMINABLE (no zone primary mapped)');
T = T.chk(isnan(f5.primary_time_s), 'F5 primary_time NaN + reason');
T = T.chk(isfinite(f5.backup_time_s) && f5.backup_time_s > 1.1 && f5.backup_time_s < 1.4, ...
    'F5 LLL remote backup_time finite ~1.23 s (LINE 3.208 kA vs GIS pickup)');

% --- Siemens-baseline backup rows: DT-?? -> NaN + ?? reason, use_phase5_time respected ---
bl = E(strcmp(E.backup_function, 'GEN-51-SIEMENS-BL'), :);
T = T.chk(height(bl) == 8, '8 Siemens-baseline backup rows (F1 x 2 cases x 4 types)');
T = T.chk(all(strcmp(bl.fault_location, 'F1')), 'baseline rows duplicate F1 generator-zone scope only');
T = T.chk(all(isnan(bl.backup_time_s)), 'baseline backup_time all NaN (DT-?? inverse prohibited)');
T = T.chk(all(cellfun(@(s) ~isempty(strfind(s, 'DT-??')), bl.not_determinable)), 'baseline reasons carry DT-??');
T = T.chk(all(cellfun(@(s) ~isempty(strfind(s, 'use_phase5_time-false')) || ~isempty(strfind(s, 'use_phase5_time')), bl.not_determinable)), ...
    'baseline reasons record use_phase5_time=false (never dispatched to phase5_time)');
T = T.chk(all(cellfun(@(s) ~isempty(strfind(s, '??')), bl.not_determinable)), 'baseline reasons carry ?? pending-coordination flag');
T = T.chk(all(strcmp(bl.primary_function, 'GEN-87G') & strcmp(bl.primary_availability, 'ASSERTABLE-DETECT')), ...
    'baseline rows keep 87G ASSERTABLE-DETECT primary (backup-layer split only)');
T = T.chk(all(abs(bl.primary_time_s - 0.045) < 1e-12), 'baseline rows keep 45 ms primary (F1/87G + 52G)');
% Frozen-library refusal of the DT-?? curve holds live (inverse path never taken).
try
    phase5_time(2 * 1.1447, 1.1447, 3.00, 'DT-??');
    T = T.chk(false, 'phase5_time refuses DT-?? curve (baseline never dispatched)');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5', 6), 'phase5_time DT-?? refusal phase5-prefixed');
end

% --- Totals / branch-doctrine guards on module source ---
src = fileread(which('phase5b_effectiveness'));
T = T.chk(isempty(strfind(src, '43758')), 'totals ban: banned total literal absent');
T = T.chk(isempty(strfind(src, 'I_primary')), 'totals ban: I_primary never referenced');
T = T.chk(isempty(strfind(src, 'Irms_kA')), 'totals ban: Irms_kA never referenced');
T = T.chk(isempty(strfind(src, 'leg_GEN_kA')), 'branch ban: T40 leg columns never read (B-table only)');
T = T.chk(isempty(strfind(src, 'leg_LINE_total_kA')), 'branch ban: T40 LINE_total column never read (F4-safe)');
T = T.chk(isempty(strfind(src, 'leg_GSUT_HV_kA')), 'branch ban: T40 GSUT leg column never read');
T = T.chk(isempty(strfind(src, 'leg_GRID_kA')), 'branch ban: T40 GRID leg column never read');
T = T.chk(~isempty(strfind(src, 'leg_NER_earth_kA')), '3I0 source: T40 NER series leg ONLY (|Ia|==|Ib|==|Ic| on NER, I1=I2=0)');
T = T.chk(~isempty(strfind(src, 'phase5b_branch_phasors(T40)')), 'single branch-phasor call on T40 (once per invocation)');
T = T.chk(~isempty(strfind(src, 'TOWARD THE FAULT')), 'inward-flow justification cited (phase4_contrib re-signing)');
T = T.chk(~isempty(strfind(src, 'phase5_time')), 'backup times via frozen phase5_time (read-only)');
T = T.chk(isempty(strfind(src, '43758')) && isempty(strfind(src, 'phase5_curve(')), ...
    'phase5_curve never called directly (only via phase5_time) OR totals absent');
T = T.chk(~isempty(strfind(src, 'use_phase5_time')), 'use_phase5_time flag respected in code');
T = T.chk(isempty(strfind(src, 'FLOOR')), 'floor ban: no FLOOR constant anywhere (sourced 0.30pu start only)');
srcNoUnits = strrep(strrep(strrep(src, '1000', ''), '100kA', ''), '100 kA', '');
T = T.chk(isempty(strfind(srcNoUnits, '100')), 'floor ban: no 100 A floor literal (only 1000 unit conversions + 100kA breaker rating permitted)');

% --- Errors phase5b-prefixed ---
try
    phase5b_effectiveness();
    T = T.chk(false, 'no-args errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'no-args error phase5b-prefixed');
end
try
    phase5b_effectiveness(table(), devices);
    T = T.chk(false, 'empty table errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'schema error phase5b-prefixed');
end
try
    phase5b_effectiveness(T40, 'not-a-struct');
    T = T.chk(false, 'bad devices errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'devices error phase5b-prefixed');
end

[np, nf] = T.done();
end

function r = row(E, loc, typ, cs, backup)
