hit = strcmp(E.fault_location, loc) & strcmp(E.fault_type, typ) ...
    & strcmp(E.caseID, cs) & strcmp(E.backup_function, backup);
if sum(hit) == 1
    r = table2struct(E(hit, :));
else
    r = [];
end
end

