function [np, nf] = test_phase5b_tcc()
%TEST_PHASE5B_TCC  Phase-5b Task C10 two-class TCC plots (physical DT vs study SI).
%   Class A (physical): GEN definite-time I> vertical at 17171 A primary
%   (1.1447 A secondary) + horizontal 3 s line DASHED and labelled ??
%   PENDING-COORDINATION (never solid); 87G pickup band marker at 0.20pu
%   approx 2403.8 A (vertical band, no curve invented).
%   Class B (study): SI curves TMS 0.20 with v2 pickups via 1600/1 CTs
%   (GEN 17170.8 A, GSUT 1380 A, GIS formula) using frozen phase5_curve
%   read-only. Outputs results/phase5_protection_v2/plots/tcc_physical.png
%   + tcc_study.png (v1 plots dir untouched). No maker strings in plot
%   text; classes in SEPARATE files. Headless-safe (Visible off). TDD RED
%   note: first run fails with undefined function phase5b_tcc.
T = t_case('test_phase5b_tcc');
root = ashuganj_root();
S = phase5b_tcc();
T = T.chk(isstruct(S) && isfield(S, 'physical_png') && isfield(S, 'study_png'), ...
    'phase5b_tcc returns struct with physical_png/study_png');
expPhys = fullfile(root, 'results', 'phase5_protection_v2', 'plots', 'tcc_physical.png');
expStudy = fullfile(root, 'results', 'phase5_protection_v2', 'plots', 'tcc_study.png');
T = T.chk(strcmp(S.physical_png, expPhys), 'physical PNG path results/phase5_protection_v2/plots/tcc_physical.png');
T = T.chk(strcmp(S.study_png, expStudy), 'study PNG path results/phase5_protection_v2/plots/tcc_study.png');
T = T.chk(~strcmp(S.physical_png, S.study_png), 'classes in SEPARATE files (paths differ)');
T = T.chk(exist(expPhys, 'file') == 2, 'tcc_physical.png exists');
T = T.chk(exist(expStudy, 'file') == 2, 'tcc_study.png exists');
d1 = dir(expPhys); d2 = dir(expStudy);
T = T.chk(d1.bytes > 0, 'tcc_physical.png non-zero bytes');
T = T.chk(d2.bytes > 0, 'tcc_study.png non-zero bytes');
% --- Class A physical DT numeric pins ---
T = T.chk(isfield(S, 'dt_Is_prim') && isfield(S, 'dt_Is_sec') && isfield(S, 'tdef_s'), ...
    'S carries dt_Is_prim/dt_Is_sec/tdef_s');
T = T.chk(abs(S.dt_Is_prim - 17171) / 17171 < 0.005, 'physical DT vertical 17171 A primary +-0.5%');
T = T.chk(abs(S.dt_Is_sec - 1.1447) / 1.1447 < 0.005, 'physical DT secondary 1.1447 A +-0.5%');
T = T.chk(abs(S.dt_Is_sec - S.dt_Is_prim / 15000) / S.dt_Is_sec < 1e-12, 'physical DT secondary consistency Is/15000');
T = T.chk(abs(S.tdef_s - 3.00) < 1e-12, 'physical tdef 3.00 s');
% Live recomputation via v2 pickup engine (baseline row found by ansi, no id hard-code).
R = phase5b_registry();
bl = [];
for k = 1:numel(R.devices)
    a = R.devices(k).ansi;
    if isstring(a) && isscalar(a), a = char(a); end
    L = R.devices(k).layer;
    if isstring(L) && isscalar(L), L = char(L); end
    if ischar(a) && strcmp(strtrim(a), '50/51-DT') && ischar(L) && strcmp(strtrim(L), 'PHYSICAL')
        bl = R.devices(k); break;
    end
end
T = T.chk(~isempty(bl), 'baseline DT row found in registry by ansi 50/51-DT PHYSICAL');
Pb = phase5b_pickup(bl, 9.47574312698307*1000, 43758.8597559);
T = T.chk(abs(S.dt_Is_prim - Pb.setting) / Pb.setting < 1e-12, 'DT Is matches live phase5b_pickup baseline setting');
T = T.chk(abs(S.dt_Is_sec - Pb.setting_sec_A) / Pb.setting_sec_A < 1e-12, 'DT Is_sec matches live baseline secondary');
T = T.chk(abs(S.tdef_s - Pb.tdef) < 1e-12, 'tdef matches live baseline tdef');
% DT line labelled ?? PENDING, horizontal DASHED never solid.
T = T.chk(isfield(S, 'dt_label') && isfield(S, 'tdef_label'), 'S carries dt_label/tdef_label');
T = T.chk(~isempty(strfind(S.dt_label, '??')), 'DT vertical label carries ??');
T = T.chk(~isempty(strfind(S.tdef_label, '??')), 'tdef horizontal label carries ??');
T = T.chk(~isempty(strfind(S.tdef_label, 'PENDING')), 'tdef label carries PENDING');
T = T.chk(isfield(S, 'dt_hline_style') && strcmp(S.dt_hline_style, '--'), 'tdef horizontal DASHED -- (never solid)');
T = T.chk(~strcmp(S.dt_hline_style, '-'), 'tdef horizontal never solid -');
T = T.chk(isfield(S, 'physical_labels'), 'S carries physical_labels');
foundQ = false; foundPend = false;
for k = 1:numel(S.physical_labels)
    lab = S.physical_labels{k};
    if isstring(lab) && isscalar(lab), lab = char(lab); end
    if ischar(lab) && ~isempty(strfind(lab, '??')), foundQ = true; end
    if ischar(lab) && ~isempty(strfind(lab, 'PENDING')), foundPend = true; end
end
T = T.chk(foundQ, 'physical labels carry ?? (pending-coordination)');
T = T.chk(foundPend, 'physical labels carry PENDING');
% --- 87G band marker, no curve invented ---
T = T.chk(isfield(S, 'pickup_87G_A') && isfield(S, 'pickup_87G_pu'), 'S carries pickup_87G_A/pu');
T = T.chk(abs(S.pickup_87G_pu - 0.20) < 1e-12, '87G start 0.20pu');
T = T.chk(abs(S.pickup_87G_A - 0.20*12019) / (0.20*12019) < 1e-9, '87G band 0.20pu x 12019 = 2403.8 A');
T = T.chk(abs(S.pickup_87G_A - 2403.8) / 2403.8 < 1e-9, '87G band approx 2403.8 A');
found87 = false; foundBand = false; foundNoCurve = false;
for k = 1:numel(S.physical_labels)
    lab = S.physical_labels{k};
    if isstring(lab) && isscalar(lab), lab = char(lab); end
    if ~ischar(lab), continue; end
    low = lower(lab);
    if ~isempty(strfind(lab, '87G')), found87 = true; end
    if ~isempty(strfind(low, 'band')), foundBand = true; end
    if ~isempty(strfind(low, 'no curve')), foundNoCurve = true; end
end
T = T.chk(found87, 'physical labels carry 87G band marker');
T = T.chk(foundBand, 'physical labels state band (not curve)');
T = T.chk(foundNoCurve, 'physical labels state no curve invented for 87G');
T = T.chk(~isfield(S, 'curve_87G'), 'no 87G curve data invented (no curve_87G field)');
% --- Class B study SI numeric pins ---
T = T.chk(isfield(S, 'study_settings'), 'S carries study_settings');
T = T.chk(numel(S.study_settings) == 3, 'study has 3 SI curves');
sids = {S.study_settings.device_id};
T = T.chk(any(strcmp(sids, 'GEN-51')), 'study carries GEN-51');
T = T.chk(any(strcmp(sids, 'GSUT-HV-51')), 'study carries GSUT-HV-51');
T = T.chk(any(strcmp(sids, 'GIS-Q0-51')), 'study carries GIS-Q0-51');
for k = 1:numel(S.study_settings)
    s = S.study_settings(k);
    T = T.chk(abs(s.TMS - 0.20) < 1e-12, ['study TMS 0.20: ' s.device_id]);
    T = T.chk(strcmp(s.curve, 'SI'), ['study curve SI: ' s.device_id]);
end
g = S.study_settings(strcmp(sids, 'GEN-51'));
T = T.chk(abs(g.pickup_prim - 17170.8) / 17170.8 < 1e-9, 'study GEN-51-SI 17170.8 A');
T = T.chk(g.ct == 15000, 'study GEN CT 15000/1');
T = T.chk(abs(g.pickup_sec - 17170.8/15000) / (17170.8/15000) < 1e-12, 'study GEN secondary Is/15000');
h = S.study_settings(strcmp(sids, 'GSUT-HV-51'));
T = T.chk(abs(h.pickup_prim - 1380) / 1380 < 1e-9, 'study GSUT 1380 A');
T = T.chk(h.ct == 1600, 'study GSUT CT 1600/1');
T = T.chk(abs(h.pickup_sec - 1380/1600) / (1380/1600) < 1e-12, 'study GSUT secondary 1380/1600');
q = S.study_settings(strcmp(sids, 'GIS-Q0-51'));
T = T.chk(abs(q.pickup_prim - 1.2*869.956651959241) / q.pickup_prim < 1e-12, 'study GIS formula 1.2x869.956652');
T = T.chk(q.ct == 1600, 'study GIS CT 1600/1');
T = T.chk(abs(q.pickup_sec - q.pickup_prim/1600) / q.pickup_sec < 1e-12, 'study GIS secondary Is/1600');
% Live recomputation via phase5b_pickup (v2 pickups, never hard-coded numbers alone).
ids = {R.devices.device_id};
Pg = phase5b_pickup(R.devices(strcmp(ids, 'GEN-51')), 9.47574312698307*1000, 43758.8597559);
T = T.chk(abs(g.pickup_prim - Pg.setting) / Pg.setting < 1e-12, 'GEN study Is matches live phase5b_pickup');
Ps = phase5b_pickup(R.devices(strcmp(ids, 'GSUT-HV-51')), 870.772573866956, 43758.8597559);
T = T.chk(abs(h.pickup_prim - Ps.setting) / Ps.setting < 1e-12, 'GSUT study Is matches live phase5b_pickup');
Pq = phase5b_pickup(R.devices(strcmp(ids, 'GIS-Q0-51')), 869.956651959241, 43758.8597559);
T = T.chk(abs(q.pickup_prim - Pq.setting) / Pq.setting < 1e-12, 'GIS study Is matches live phase5b_pickup');
% Study times reproduce frozen library phase5_curve (read-only use).
T = T.chk(isfield(S, 'study_times'), 'S carries study_times at 2x Is');
tLib = phase5_curve(2.0, 'SI', 0.20);
for k = 1:numel(S.study_settings)
    s = S.study_settings(k);
    tGot = S.study_times(k);
    tExp = phase5_time(2*s.pickup_sec, s.pickup_sec, s.TMS, s.curve);
    T = T.chk(abs(tGot - tExp) < 1e-9, ['study time matches phase5_time library: ' s.device_id]);
    T = T.chk(abs(tGot - tLib) < 1e-9, ['study time matches phase5_curve SI TMS 0.20: ' s.device_id]);
end
% Labels carry device/CT/TMS/curve tokens.
T = T.chk(isfield(S, 'study_labels'), 'S carries study_labels');
T = T.chk(allTok(S.study_labels, 'CT'), 'study labels carry CT token');
T = T.chk(allTok(S.study_labels, 'TMS'), 'study labels carry TMS token');
T = T.chk(allTok(S.study_labels, 'SI'), 'study labels carry SI token');
T = T.chk(hasTok(S.study_labels, 'GEN-51'), 'study labels carry GEN-51');
T = T.chk(hasTok(S.study_labels, 'GSUT-HV-51'), 'study labels carry GSUT-HV-51');
T = T.chk(hasTok(S.study_labels, 'GIS-Q0-51'), 'study labels carry GIS-Q0-51');
% No maker strings in plot text (titles/labels/footers).
allTxt = [S.physical_title ' ' S.study_title ' ' ...
    strjoin(cellstr(S.physical_labels), ' ') ' ' strjoin(cellstr(S.study_labels), ' ')];
if isfield(S, 'physical_foot')
    if iscell(S.physical_foot), allTxt = [allTxt ' ' strjoin(cellstr(S.physical_foot), ' ')];
    else, allTxt = [allTxt ' ' char(S.physical_foot)]; end
end
if isfield(S, 'study_foot')
    if iscell(S.study_foot), allTxt = [allTxt ' ' strjoin(cellstr(S.study_foot), ' ')];
    else, allTxt = [allTxt ' ' char(S.study_foot)]; end
end
T = T.chk(~hasMaker(allTxt), 'no maker strings in titles/labels/footers');
% v1 plots dir untouched + frozen-library/headless pattern in source.
srcPath = fullfile(root, 'matlab', 'phase5', 'phase5b_tcc.m');
src = fileread(srcPath);
T = T.chk(~isempty(strfind(src, 'phase5_protection_v2')), 'source writes v2 dir (phase5_protection_v2)');
T = T.chk(isempty(strfind(src, '''phase5_protection''')), 'source never references v1 plots dir (untouched)');
T = T.chk(isempty(strfind(src, 'tcc_gen.png')) && isempty(strfind(src, 'tcc_grid.png')), 'source never writes v1 filenames (untouched)');
T = T.chk(~isempty(strfind(src, 'tcc_physical.png')) && ~isempty(strfind(src, 'tcc_study.png')), 'source writes both v2 filenames');
T = T.chk(~isempty(strfind(src, 'phase5_curve(')), 'source uses frozen phase5_curve read-only');
T = T.chk(~isempty(strfind(src, 'phase5b_pickup')) && ~isempty(strfind(src, 'phase5b_registry')), 'source uses v2 registry+pickup (never hard-coded)');
T = T.chk(~isempty(strfind(src, 'Visible')) && ~isempty(strfind(src, 'off')), 'source headless-safe (Visible off)');
% Errors phase5b-prefixed.
try
    phase5b_tcc(42);
    T = T.chk(false, 'bad outDir errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'bad outDir errors phase5b-prefixed');
end
[np, nf] = T.done();
end

function ok = hasTok(labels, tok)
ok = false;
key = [tok ' |'];
for k = 1:numel(labels)
    lab = labels{k};
    if isstring(lab) && isscalar(lab), lab = char(lab); end
    if ischar(lab) && ~isempty(strfind(lab, key)), ok = true; return; end
    if ischar(lab) && ~isempty(strfind(lab, tok)) && k <= numel(labels), ok = true; return; end
end
end

function ok = allTok(labels, tok)
ok = true;
for k = 1:numel(labels)
    lab = labels{k};
    if isstring(lab) && isscalar(lab), lab = char(lab); end
    if ~ischar(lab) || isempty(strfind(lab, tok)), ok = false; return; end
end
end

function bad = hasMaker(txt)
low = lower(txt);
subs = {'siemens', 'schneider', 'alstom', 'micom', 'areva', 'hitachi', ...
    'toshiba', 'siprotec', 'reyrolle', 'general electric'};
bad = false;
for k = 1:numel(subs)
    if ~isempty(strfind(low, subs{k})), bad = true; return; end
end
words = regexp(low, '[a-z0-9]+', 'match');
if any(strcmp(words, 'abb')) || any(strcmp(words, 'sel')), bad = true; end
end

