%         / inverse-prohibited via use_phase5_time false + frozen-library
%         refusal).
%     B03 Variant separation (STUDY GEN-51 distinct from PHYSICAL baseline;
%         alias GEN-51-SI; SI/TMS-0.20/inverse-allowed; DISABLED high-set).
%     B04 Branch-not-total (43758 absent from DETECTION logic). Scan targets
%         detection modules (mindetect/effectiveness/pickup), NOT plot
%         labels: 43758.86 legitimately appears as Imin REFERENCE arg in
%         phase5b_tcc (IMIN_PHASE_A into phase5b_pickup shape arg + study
%         time anchor per C10 review) and is excluded by design. Documented
%         in-test below + in the B04 leg note.
%     B05 52G presence + 100 kA (GEN-52G PHYSICAL SOURCE-BACKED 10BAC10
%         12.4 kA cont / 100 kA breaking; topology 10BAC10/100; duty 52G
%         F1 LLL OUT PASS).
%     B06 Zone mapping + F-mapping (G/T/B/L; F1->87G, F2->87T, F3->87B,
%         F4->7SD; trip fields NOT-DETERMINABLE).
%     B07 F3->87B detect-vs-time split (NOT-DETERMINABLE + NaN time with
%         no-sourced-7SS523-pickup reason; study backup finite via frozen
%         phase5_time).
%     B08 F4->7SD (NOT-DETERMINABLE + NaN time with no-sourced-7SD5221
%         reason; B1-outfeed backups finite, never cancellation residual).
%     B09 51N/59N/64G split (51N-SI-STUDY 5 A SENSITIVITY TMS 0.15; 59N/64G/
%         64R PHYSICAL NaN + 381.05 VT datum; 64G never 3I0 pickup) + F2-LG-
%         backup consistency probe from C8 concern (F2 LG backup is
%         GSUT-HV-51 phase, never GEN-51N; finite time).
%     B10 Rating split (equipment~=interrupting: Q0 rating NaN + equipment
%         50 EQUIPMENT WITHSTAND never interrupting; 52G rating 100 +
%         equipment NaN MISSING; NOTE never PASS/FAIL with split fields).
%     B11 8.414 kA trace (re-asserts C5 key identities live; does NOT nest
%         runners: never calls test_phase5b_branch_audit or
%         run_phase5b_tests -- re-assertion only, by design).
%     B12 No-conflation (no PHYSICAL row carries STUDY numbers and vice
%         versa -- cross-scan registry + pickup engine).
%     B13 R0 identity (same tolerances as v1 R0, v2 path).
%   Runner contract (run_phase5b_tests.m, asserted structurally here, never
%   invoked -- invoking it would nest the ~5-min effectiveness recompute):
%     new file matlab/phase5/run_phase5b_tests.m runs test_phase5b_* +
%     phase5b_validate, prints counts, errors phase5b-prefixed; v1
%     run_phase5_tests.m frozen untouched.
%   All errors phase5b-prefixed.
%
%   TDD RED note: first run fails with undefined function phase5b_validate
%   as required; GREEN after module creation. Effectiveness recompute inside
%   validate takes minutes -- this suite calls validate ONCE and reuses V.
T = t_case('test_phase5b_validate');

% --- Single validate call (minutes via one effectiveness recompute) ---
V = phase5b_validate();
T = T.chk(isstruct(V) && isfield(V, 'legs'), 'V struct with .legs');
T = T.chk(isstruct(V.legs), 'legs struct array');
wantIds = {'R0', 'B01', 'B02', 'B03', 'B04', 'B05', 'B06', 'B07', ...
    'B08', 'B09', 'B10', 'B11', 'B12', 'B13'};
T = T.chk(numel(V.legs) == 14, '14 legs (R0 + B01-B13)');
ids = {V.legs.id};
T = T.chk(isequal(ids, wantIds), 'leg ids R0,B01-B13 in locked order');
for k = 1:numel(V.legs)
    T = T.chk(ischar(V.legs(k).id) && ~isempty(V.legs(k).id), ['leg id char: ' V.legs(k).id]);
    T = T.chk(islogical(V.legs(k).pass) && isscalar(V.legs(k).pass), ['leg pass logical: ' V.legs(k).id]);
    T = T.chk(isnumeric(V.legs(k).residual) && isscalar(V.legs(k).residual) && isfinite(V.legs(k).residual), ['leg residual finite: ' V.legs(k).id]);
    T = T.chk(ischar(V.legs(k).note) && ~isempty(strtrim(V.legs(k).note)), ['leg note non-empty: ' V.legs(k).id]);
    T = T.chk(V.legs(k).pass, ['leg passes: ' V.legs(k).id]);
end

% --- R0/B13 re-import identity spot (v1 tolerances) ---
r0 = V.legs(strcmp(ids, 'R0'));
b13 = V.legs(strcmp(ids, 'B13'));
T = T.chk(r0.residual < 1e-6, 'R0 residual < 1e-6 (v1 tolerances)');
T = T.chk(b13.residual < 1e-6, 'B13 residual < 1e-6 (same tolerances as v1 R0)');
T = T.chk(~isempty(strfind(r0.note, '50.530')) && ~isempty(strfind(r0.note, '0.00727')), 'R0 note quotes F3/F1 anchors');
T = T.chk(~isempty(strfind(b13.note, 'v1 R0')) || ~isempty(strfind(b13.note, 'v1-R0')) || ~isempty(strfind(lower(b13.note), 'same tolerances')), 'B13 note records v1-tolerance identity');

% --- B02 Siemens baseline spot ---
b02 = V.legs(strcmp(ids, 'B02'));
T = T.chk(b02.residual < 0.005, 'B02 residual < 0.5% band');
T = T.chk(~isempty(strfind(b02.note, '17171')) && ~isempty(strfind(b02.note, 'DT-??')), 'B02 note carries 17171 + DT-??');

% --- B04 branch-not-total distinction (detection vs plot-label Imin REFERENCE) ---
b04 = V.legs(strcmp(ids, 'B04'));
T = T.chk(~isempty(strfind(b04.note, '43758')), 'B04 note documents 43758 distinction');
T = T.chk(~isempty(strfind(b04.note, 'detection')) && (~isempty(strfind(lower(b04.note), 'tcc')) || ~isempty(strfind(b04.note, 'REFERENCE'))), 'B04 note scopes scan to detection modules, tcc REFERENCE excluded');
srcMind = fileread(which('phase5b_mindetect'));
srcEff = fileread(which('phase5b_effectiveness'));
srcPick = fileread(which('phase5b_pickup'));
T = T.chk(isempty(strfind(srcMind, '43758')), 'B04 in-test: 43758 absent from mindetect (detection)');
T = T.chk(isempty(strfind(srcEff, '43758')), 'B04 in-test: 43758 absent from effectiveness (detection)');
T = T.chk(isempty(strfind(srcPick, '43758')), 'B04 in-test: 43758 absent from pickup (detection)');
srcTcc = fileread(which('phase5b_tcc'));
T = T.chk(~isempty(strfind(srcTcc, '43758')), 'B04 in-test: 43758 legitimately present in tcc (Imin REFERENCE, excluded by design)');
T = T.chk(~isempty(strfind(srcTcc, 'IMIN_PHASE_A')) && ~isempty(strfind(srcTcc, 'phase5b_pickup')), 'B04 in-test: tcc 43758 is IMIN_PHASE_A REFERENCE arg into pickup (not detection)');

% --- B09 F2-LG-backup consistency probe spot (C8 concern) ---
b09 = V.legs(strcmp(ids, 'B09'));
T = T.chk(~isempty(strfind(b09.note, 'F2')) && ~isempty(strfind(b09.note, 'GSUT-HV-51')), 'B09 note carries F2-LG GSUT-HV-51 probe');
T = T.chk(~isempty(strfind(b09.note, '59N')) && ~isempty(strfind(b09.note, '64G')), 'B09 note carries 59N/64G split');

% --- B11 re-assertion spot (no nested runners) ---
b11 = V.legs(strcmp(ids, 'B11'));
T = T.chk(~isempty(strfind(b11.note, '8.414')), 'B11 note quotes 8.414 kA trace');
T = T.chk(~isempty(strfind(lower(b11.note), 'branch-through-current')), 'B11 note carries branch-through-current verdict');
srcVal = fileread(which('phase5b_validate'));
% No-nest scan targets live CALLS (name + open-paren), not doc mentions:
% the validator header legitimately names the C5 audit + runners in prose
% to record the no-nesting contract, so bare-name matching would trip on
% its own documentation. A real nest would be test_phase5b_branch_audit(
% or run_phase5*_tests( / feval on those names.
T = T.chk(isempty(strfind(srcVal, 'test_phase5b_branch_audit(')), 'B11 in-test: validate never calls C5 test (re-assert only)');
T = T.chk(isempty(strfind(srcVal, 'run_phase5b_tests(')) && isempty(strfind(srcVal, 'run_phase5_tests(')) && isempty(strfind(srcVal, 'feval(name)')), 'B11 in-test: validate never calls runners');

% --- Runner contract (structural only; never invoked -- would nest minutes) ---
T = T.chk(exist('run_phase5b_tests', 'file') == 2, 'runner run_phase5b_tests.m exists');
srcRun = fileread(which('run_phase5b_tests'));
T = T.chk(~isempty(strfind(srcRun, 'test_phase5b_')) && ~isempty(strfind(srcRun, 'phase5b_validate')), 'runner runs test_phase5b_* + phase5b_validate');
T = T.chk(~isempty(strfind(srcRun, 'phase5b_tests:')), 'runner prints phase5b_tests counts');
T = T.chk(~isempty(strfind(srcRun, 'phase5b')), 'runner errors phase5b-prefixed');
% Delegation scan targets a live v1-runner CALL (name + open-paren), not doc
% prose: the runner header legitimately refers to the frozen v1 runner in
% words to record the no-touch contract, so bare-name matching would trip
% on its own documentation.
T = T.chk(isempty(strfind(srcRun, 'run_phase5_tests(')), 'runner never calls frozen v1 runner');

% --- Errors phase5b-prefixed ---
try
    phase5b_validate(1);
    T = T.chk(false, 'phase5b_validate(1) errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'validate arg error phase5b-prefixed');
end

[np, nf] = T.done();
end

function [np, nf] = test_phase5b_zones()
%TEST_PHASE5B_ZONES  Phase-5b Task C7 physical registry rows + zones + 52G.
%   Locked outputs under test:
%     R = phase5b_registry() extended with PHYSICAL presence rows (C2 study
%       rows preserved 1:1) + Z = phase5b_zones() zone/device/function/role
%       table G/T/B/L with F1->87G, F2->87T, F3->87B, F4->7SD mapping.
%   Binding carry-overs (ledgered prior tasks):
%     (1) GEN-51-SIEMENS-BL + GEN-51N-SI-STUDY values mirrored 1:1 from
%         phase5b_pickup (baseline 17171 A / DT-?? / USER_ASSERTED_PENDING_DOC;
%         variant 5 A / SENSITIVITY via canonical GEN-51N).
%     (2) Canonical study IDs GEN-51/GEN-51N (layer STUDY); GEN-51-SI /
%         GEN-51N-SI-STUDY accepted as documented aliases via
%         phase5b_id_aliases (tested both ways: alias->canonical and
%         canonical->canonical idempotent + pickup equality both directions).
%     (3) Trip-matrix fields all NOT-DETERMINABLE (52G vs Q0, 86 lockout,
%         BF paths never inferred).
%   Presence rows carry settings ONLY where sourced (87G 0.20 pu
%   USER_ASSERTED_PENDING_DOC + master-S21 corroboration; 46 capability
%   I2max/K note with no pickup; 40/32R/21/78/59/81/24/50-27 MISSING;
%   59N/64G/64R + 381.05 VT datum; 7UT6331 87T; 87N; 63/49/86; 87B/7SS523;
%   7SD5221x2; 6MD66 note; 52G/10BAC10 12.4kA/100kA SOURCE-BACKED; UAT/GAT
%   per CT tables). All errors phase5b-prefixed. TDD RED note: first run
%   fails with undefined function phase5b_zones.
T = t_case('test_phase5b_zones');
R = phase5b_registry();
ids = {R.devices.device_id};
% --- Locked 26-field schema preserved (21 v1 + 5 v2) ---
T = T.chk(isstruct(R)&&isfield(R,'devices')&&isfield(R,'gen')&&isfield(R,'topology'), 'registry struct devices/gen/topology');
T = T.chk(numel(R.devices) >= 7+26, 'registry carries 7 study + 26 physical rows minimum (33 total)');
% --- C2 study rows preserved 1:1 ---
need_study = {'GEN-51','GEN-51N','GSUT-HV-51','GIS-Q0-51','GIS-Q0-50','LINE-21-note','REMOTE-GRID-boundary'};
for k = 1:numel(need_study)
    hit = strcmp(ids,need_study{k});
    T = T.chk(any(hit), ['study row preserved: ' need_study{k}]);
    if any(hit)
        T = T.chk(strcmp(R.devices(hit).layer,'STUDY'), ['study layer kept: ' need_study{k}]);
    end
end
g = R.devices(strcmp(ids,'GSUT-HV-51'));
T = T.chk(g.ct_ratio==1600 && strcmp(g.ct_source,'SOURCE-BACKED'), 'C2 GSUT 1600/1 SOURCE-BACKED kept');
q = R.devices(strcmp(ids,'GIS-Q0-51'));
T = T.chk(q.ct_ratio==1600 && strcmp(q.ct_source,'SOURCE-BACKED'), 'C2 GIS 1600/1 SOURCE-BACKED kept');
p51 = R.devices(strcmp(ids,'GEN-51'));
T = T.chk(p51.ct_ratio==15000 && isnan(p51.pickup_A) && ~isempty(strfind(p51.protection_function,'RULE-1.2xMAXLOAD')), 'C2 GEN-51 NaN + RULE tag kept');
T = T.chk(R.gen.Imax_A==14309 && strcmp(R.topology.breaker_52G,'10BAC10') && R.topology.rating_100kA==100, 'C2 gen/topology kept');
ratios = [R.devices.ct_ratio];
T = T.chk(~any(ratios==2000), 'zero ct_ratio 2000 (study+physical)');
T = T.chk(~any(ratios==16000), 'zero ct_ratio 16000');
T = T.chk(~any([R.devices.physical_CT_ratio]==2000|[R.devices.study_CT_ratio]==2000), 'zero physical/study CT 2000');
T = T.chk(~any([R.devices.physical_CT_ratio]==16000|[R.devices.study_CT_ratio]==16000), 'zero physical/study CT 16000');
% --- (1) Baseline GEN-51-SIEMENS-BL mirrored 1:1 from phase5b_pickup ---
T = T.chk(any(strcmp(ids,'GEN-51-SIEMENS-BL')), 'baseline row GEN-51-SIEMENS-BL present');
bl = R.devices(strcmp(ids,'GEN-51-SIEMENS-BL'));
T = T.chk(strcmp(bl.layer,'PHYSICAL'), 'baseline layer PHYSICAL');
T = T.chk(strcmp(bl.ansi,'50/51-DT'), 'baseline ansi 50/51-DT');
T = T.chk(strncmp(bl.provenance,'USER_ASSERTED_PENDING_DOC',25), 'baseline provenance USER_ASSERTED_PENDING_DOC');
T = T.chk(bl.ct_ratio==15000 && strcmp(bl.ct_source,'SOURCE-BACKED'), 'baseline CT 15000/1 SOURCE-BACKED');
T = T.chk(abs(bl.pickup_A-17171)/17171 < 1e-12, 'baseline pickup 17171 A mirrored');
T = T.chk(strcmp(bl.curve,'DT-??'), 'baseline curve DT-?? mirrored');
T = T.chk(isnan(bl.tms), 'baseline registry tms NaN (tdef lives in pickup, not registry)');
T = T.chk(strcmp(bl.protection_function,'50/51-DT-BASELINE'), 'baseline protection_function 50/51-DT-BASELINE');
T = T.chk(bl.physical_CT_ratio==15000 && bl.study_CT_ratio==15000, 'baseline physical/study CT 15000');
T = T.chk(strcmp(bl.status,'PENDING-DOC-INGEST'), 'baseline status PENDING-DOC-INGEST');
% Baseline pickup mirrors registry 1:1
FL_GENQ_A = 9.47574312698307*1000; IMIN_PHASE_A = 43758.8597559;
Pb = phase5b_pickup(bl, FL_GENQ_A, IMIN_PHASE_A);
T = T.chk(abs(Pb.setting-17171)/17171 < 0.005, 'pickup baseline 17171 A +-0.5%');
T = T.chk(abs(Pb.setting_sec_A-1.1447)/1.1447 < 0.005, 'pickup baseline secondary 1.1447 +-0.5%');
T = T.chk(abs(Pb.tdef-3.00) < 1e-12 && strcmp(Pb.time_status,'NOT-DETERMINABLE-??-PENDING-COORDINATION'), 'pickup baseline tdef 3.00 ?? NOT-DETERMINABLE');
T = T.chk(strcmp(Pb.curve,'DT-??') && islogical(Pb.use_phase5_time) && ~Pb.use_phase5_time, 'pickup baseline inverse prohibited DT-??/false');
T = T.chk(~isempty(strfind(Pb.source,'USER_ASSERTED_PENDING_DOC')), 'pickup baseline source USER_ASSERTED_PENDING_DOC');
% --- (1) Variant GEN-51N-SI-STUDY 5 A / SENSITIVITY via canonical GEN-51N ---
T = T.chk(any(strcmp(ids,'GEN-51N')), 'canonical GEN-51N present (STUDY)');
ge = R.devices(strcmp(ids,'GEN-51N'));
T = T.chk(strcmp(ge.layer,'STUDY') && ge.ct_ratio==15000, 'canonical GEN-51N STUDY 15000/1');
Pe = phase5b_pickup(ge, 0, 7.27200442799167);
T = T.chk(abs(Pe.setting-5) < 1e-12 && strcmp(Pe.assumption_class,'SENSITIVITY'), 'variant 5 A SENSITIVITY mirrored via canonical');
ge2 = ge; ge2.device_id = 'GEN-51N-SI-STUDY';
Pe2 = phase5b_pickup(ge2, 0, 7.27200442799167);
T = T.chk(abs(Pe2.setting-5) < 1e-12, 'alias GEN-51N-SI-STUDY 5 A');
% --- (2) Alias map both ways ---
T = T.chk(strcmp(phase5b_id_aliases('GEN-51-SI'),'GEN-51'), 'alias GEN-51-SI -> GEN-51');
T = T.chk(strcmp(phase5b_id_aliases('GEN-51N-SI-STUDY'),'GEN-51N'), 'alias GEN-51N-SI-STUDY -> GEN-51N');
T = T.chk(strcmp(phase5b_id_aliases('GEN-51'),'GEN-51'), 'canonical GEN-51 idempotent');
T = T.chk(strcmp(phase5b_id_aliases('GEN-51N'),'GEN-51N'), 'canonical GEN-51N idempotent');
T = T.chk(strcmp(phase5b_id_aliases('GEN-51-SIEMENS-BL'),'GEN-51-SIEMENS-BL'), 'baseline idempotent (not an alias)');
Pg = phase5b_pickup(p51, FL_GENQ_A, IMIN_PHASE_A);
ga = p51; ga.device_id = 'GEN-51-SI';
Pa = phase5b_pickup(ga, FL_GENQ_A, IMIN_PHASE_A);
T = T.chk(abs(Pa.setting-Pg.setting)/Pg.setting < 1e-12, 'alias GEN-51-SI pickup equals canonical both ways');
T = T.chk(abs(Pe2.setting-Pe.setting) < 1e-12, 'alias GEN-51N-SI-STUDY pickup equals canonical both ways');
% --- Physical presence rows: 87G sourced setting ---
T = T.chk(any(strcmp(ids,'GEN-87G')), 'presence GEN-87G');
d87 = R.devices(strcmp(ids,'GEN-87G'));
T = T.chk(strcmp(d87.layer,'PHYSICAL') && strcmp(d87.ansi,'87G'), 'GEN-87G PHYSICAL 87G');
T = T.chk(strncmp(d87.provenance,'USER_ASSERTED_PENDING_DOC',25), 'GEN-87G provenance USER_ASSERTED_PENDING_DOC');
T = T.chk(~isempty(strfind(d87.provenance,'0.20')) && ~isempty(strfind(d87.protection_function,'0.20')), 'GEN-87G start 0.20 recorded');
T = T.chk(~isempty(strfind(d87.protection_function,'master'))||~isempty(strfind(d87.provenance,'master')), 'GEN-87G master-S21 corroboration note');
T = T.chk(abs(d87.pickup_A-0.20*12019)/(0.20*12019) < 1e-9, 'GEN-87G pickup 0.20pu x 12019 = 2403.8 A');
% --- 46 capability note, no pickup invented ---
T = T.chk(any(strcmp(ids,'GEN-46')), 'presence GEN-46');
d46 = R.devices(strcmp(ids,'GEN-46'));
T = T.chk(strcmp(d46.layer,'PHYSICAL') && strcmp(d46.ansi,'46'), 'GEN-46 PHYSICAL 46');
T = T.chk(isnan(d46.pickup_A), 'GEN-46 no pickup invented (NaN)');
T = T.chk(~isempty(strfind(d46.protection_function,'I2max'))||~isempty(strfind(d46.provenance,'I2max')), 'GEN-46 I2max capability note');
T = T.chk(~isempty(strfind(d46.protection_function,'K'))||~isempty(strfind(d46.provenance,'K')), 'GEN-46 K capability note');
% --- 40/32R/21/78/59/81/24/50-27 presence MISSING ---
miss_ids = {'GEN-40','GEN-32R','GEN-21','GEN-78','GEN-59','GEN-81','GEN-24','GEN-50-27'};
for k = 1:numel(miss_ids)
    T = T.chk(any(strcmp(ids,miss_ids{k})), ['presence ' miss_ids{k}]);
    if any(strcmp(ids,miss_ids{k}))
        d = R.devices(strcmp(ids,miss_ids{k}));
        T = T.chk(strcmp(d.layer,'PHYSICAL'), ['PHYSICAL layer: ' miss_ids{k}]);
        T = T.chk(isnan(d.pickup_A), ['MISSING pickup NaN: ' miss_ids{k}]);
        T = T.chk(strncmp(d.provenance,'MISSING',7), ['MISSING provenance: ' miss_ids{k}]);
    end
end
% --- 59N/64G/64R + 381.05 VT datum ---
for k = 1:numel({'GEN-59N','GEN-64G','GEN-64R'})
    mid = {'GEN-59N','GEN-64G','GEN-64R'}; id = mid{k};
    T = T.chk(any(strcmp(ids,id)), ['presence ' id]);
    if any(strcmp(ids,id))
        d = R.devices(strcmp(ids,id));
        T = T.chk(strcmp(d.layer,'PHYSICAL') && isnan(d.pickup_A), [id ' PHYSICAL no invented pickup']);
        blob = [d.provenance ' ' d.protection_function];
        T = T.chk(~isempty(strfind(blob,'381.05')), [id ' 381.05 VT datum']);
    end
end
% --- 7UT6331 87T; 87N; 63/49/86 ---
T = T.chk(any(strcmp(ids,'GSUT-87T')), 'presence GSUT-87T');
t87 = R.devices(strcmp(ids,'GSUT-87T'));
T = T.chk(strcmp(t87.layer,'PHYSICAL') && strcmp(t87.ansi,'87T'), 'GSUT-87T PHYSICAL 87T');
T = T.chk(~isempty(strfind([t87.provenance ' ' t87.protection_function ' ' t87.selected_CT_core],'7UT6331'))||~isempty(strfind([t87.provenance ' ' t87.protection_function],'87T')), 'GSUT-87T 7UT6331/87T trace');
T = T.chk(isnan(t87.pickup_A), 'GSUT-87T no invented pickup');
for k = 1:numel({'GSUT-87N','GSUT-63','GSUT-49','GSUT-86'})
    nid = {'GSUT-87N','GSUT-63','GSUT-49','GSUT-86'}; id = nid{k};
    T = T.chk(any(strcmp(ids,id)), ['presence ' id]);
    if any(strcmp(ids,id))
        d = R.devices(strcmp(ids,id));
        T = T.chk(strcmp(d.layer,'PHYSICAL') && isnan(d.pickup_A), [id ' PHYSICAL no invented pickup']);
    end
end
% --- 87B/7SS523; 7SD5221x2; 6MD66 ---
T = T.chk(any(strcmp(ids,'GIS-87B')), 'presence GIS-87B');
b87 = R.devices(strcmp(ids,'GIS-87B'));
T = T.chk(strcmp(b87.layer,'PHYSICAL') && strcmp(b87.ansi,'87B'), 'GIS-87B PHYSICAL 87B');
T = T.chk(~isempty(strfind([b87.provenance ' ' b87.protection_function],'7SS523')), 'GIS-87B 7SS523 trace');
T = T.chk(any(strcmp(ids,'LINE-7SD')), 'presence LINE-7SD');
l7 = R.devices(strcmp(ids,'LINE-7SD'));
T = T.chk(strcmp(l7.layer,'PHYSICAL'), 'LINE-7SD PHYSICAL');
T = T.chk(~isempty(strfind([l7.provenance ' ' l7.protection_function],'7SD5221')), 'LINE-7SD 7SD5221x2 trace');
T = T.chk(any(strcmp(ids,'GIS-6MD66')), 'presence GIS-6MD66');
m66 = R.devices(strcmp(ids,'GIS-6MD66'));
T = T.chk(strcmp(m66.layer,'PHYSICAL') && ~isempty(strfind([m66.provenance ' ' m66.protection_function],'6MD66')), 'GIS-6MD66 bay-control note');
% --- 52G/10BAC10 12.4kA/100kA SOURCE-BACKED ---
T = T.chk(any(strcmp(ids,'GEN-52G')), 'presence GEN-52G');
br = R.devices(strcmp(ids,'GEN-52G'));
T = T.chk(strcmp(br.layer,'PHYSICAL'), 'GEN-52G PHYSICAL');
T = T.chk(strncmp(br.provenance,'SOURCE-BACKED',13), 'GEN-52G provenance SOURCE-BACKED');
