T = T.chk(~isempty(strfind(blob52,'100')) && ~isempty(strfind(blob52,'12.4')), 'GEN-52G 12.4kA/100kA ratings');
% --- UAT/GAT per CT tables ---
T = T.chk(any(strcmp(ids,'UAT-HV-51')), 'presence UAT-HV-51');
u = R.devices(strcmp(ids,'UAT-HV-51'));
T = T.chk(u.ct_ratio==1000 && strcmp(u.ct_source,'SOURCE-BACKED'), 'UAT CT 1000/1 SOURCE-BACKED');
T = T.chk(any(strcmp(ids,'GAT-HVN-51N')), 'presence GAT-HVN-51N');
gv = R.devices(strcmp(ids,'GAT-HVN-51N'));
T = T.chk(gv.ct_ratio==250 && strcmp(gv.ct_source,'SOURCE-BACKED'), 'GAT CT 250/1 SOURCE-BACKED');
% --- 50BF presence ---
T = T.chk(any(strcmp(ids,'GIS-50BF')), 'presence GIS-50BF');
% --- Settings ONLY where sourced: no PHYSICAL pickup except baseline/87G ---
for i = 1:numel(R.devices)
    d = R.devices(i);
    if strcmp(d.layer,'PHYSICAL')
        isSrc = any(strcmp(d.device_id,{'GEN-51-SIEMENS-BL','GEN-87G'}));
        if ~isSrc
            T = T.chk(isnan(d.pickup_A), ['PHYSICAL no invented pickup: ' d.device_id]);
        end
        T = T.chk(isnan(d.tms) && isnan(d.ef_pickup_A) && isnan(d.ef_tms), ['PHYSICAL no TMS/EF invented: ' d.device_id]);
    end
end
% --- (3) Trip matrix NOT-DETERMINABLE on registry + zones ---
for i = 1:numel(R.devices)
    d = R.devices(i);
    if strcmp(d.layer,'PHYSICAL')
        T = T.chk(isempty(d.breaker_ref)||strcmp(d.breaker_ref,'NOT-DETERMINABLE'), ['PHYSICAL trip breaker_ref NOT-DETERMINABLE: ' d.device_id]);
    end
end
% --- Zones table G/T/B/L + F-mapping ---
Z = phase5b_zones();
T = T.chk(isstruct(Z), 'zones struct array');
T = T.chk(all(isfield(Z,{'zone','device_id','ansi','role','primary_for_fault','trip_52G','trip_Q0','lockout_86','bf_path'})), 'zones locked fields');
zones = {Z.zone};
T = T.chk(any(strcmp(zones,'G'))&&any(strcmp(zones,'T'))&&any(strcmp(zones,'B'))&&any(strcmp(zones,'L')), 'zones G/T/B/L all present');
pf = @(f) Z(strcmp({Z.primary_for_fault},f));
z1 = pf('F1'); T = T.chk(numel(z1)==1 && strcmp(z1.ansi,'87G'), 'F1->87G primary mapping');
z2 = pf('F2'); T = T.chk(numel(z2)==1 && strcmp(z2.ansi,'87T'), 'F2->87T primary mapping');
z3 = pf('F3'); T = T.chk(numel(z3)==1 && strcmp(z3.ansi,'87B'), 'F3->87B primary mapping');
z4 = pf('F4'); T = T.chk(numel(z4)==1 && ~isempty(strfind(z4.ansi,'7SD')), 'F4->7SD primary mapping');
for i = 1:numel(Z)
    T = T.chk(strcmp(Z(i).trip_52G,'NOT-DETERMINABLE'), ['trip_52G NOT-DETERMINABLE: ' Z(i).device_id]);
    T = T.chk(strcmp(Z(i).trip_Q0,'NOT-DETERMINABLE'), ['trip_Q0 NOT-DETERMINABLE: ' Z(i).device_id]);
    T = T.chk(strcmp(Z(i).lockout_86,'NOT-DETERMINABLE'), ['86 lockout NOT-DETERMINABLE: ' Z(i).device_id]);
    T = T.chk(strcmp(Z(i).bf_path,'NOT-DETERMINABLE'), ['BF path NOT-DETERMINABLE: ' Z(i).device_id]);
    T = T.chk(any(strcmp(ids,Z(i).device_id)), ['zones device in registry: ' Z(i).device_id]);
end
% --- Errors phase5b-prefixed ---
try
    phase5b_zones(1);
    T = T.chk(false, 'phase5b_zones(1) errors');
catch ME
    T = T.chk(strncmp(ME.identifier,'phase5b',7), 'zones error phase5b-prefixed');
end
try
    phase5b_id_aliases();
    T = T.chk(false, 'phase5b_id_aliases() errors');
catch ME
    T = T.chk(strncmp(ME.identifier,'phase5b',7), 'alias error phase5b-prefixed');
end
try
    phase5b_id_aliases('');
    T = T.chk(false, 'alias empty errors');
catch ME
    T = T.chk(strncmp(ME.identifier,'phase5b',7), 'alias empty phase5b-prefixed');
end
[np, nf] = T.done();
end

