% Code hashes cover phase5b_* AND frozen v1 modules used.
cfiles = {M.codeHashes.file};
T = T.chk(any(strcmp(cfiles, 'phase5b_writer.m')), 'codeHashes include phase5b_writer.m');
T = T.chk(any(strcmp(cfiles, 'phase5b_registry.m')), 'codeHashes include phase5b_registry.m');
T = T.chk(any(strcmp(cfiles, 'phase5_coord.m')), 'codeHashes include frozen phase5_coord.m');
T = T.chk(any(strcmp(cfiles, 'run_phase5b_production.m')), 'codeHashes include run_phase5b_production.m');
% sha256.txt covers 12 files.
sh = strsplit(strtrim(fileread(fullfile(tmpOut, 'sha256.txt'))), '\n');
T = T.chk(numel(sh) == 12, 'sha256.txt covers 10 CSVs + manifest + run_log (12 lines)');
% Provenance whitelist: each legal class passes on a rewrite.
classes = {'SOURCE-BACKED', 'DERIVED', 'ENGINEERING_ASSUMPTION', ...
    'LEGACY', 'MISSING', 'USER_ASSERTED_PENDING_DOC'};
for k = 1:numel(classes)
    ok = tiny_tables_v2('production-v2');
    ok.faultInputs.provenance{1} = [classes{k} ':unit-test-whitelist-probe'];
    try
        phase5b_writer(fullfile(tempdir(), ['phase5b_wl_' classes{k}]), ok, meta);
        T = T.chk(true, sprintf('whitelist class legal: %s', classes{k}));
    catch ME
        T = T.chk(false, sprintf('whitelist class legal: %s (%s)', classes{k}, ME.identifier));
    end
    if exist(fullfile(tempdir(), ['phase5b_wl_' classes{k}]), 'dir') == 7
        rmdir(fullfile(tempdir(), ['phase5b_wl_' classes{k}]), 's');
    end
end
% Illegal provenance class errors phase5b_writer:provenance.
bad = tables;
bad.faultInputs.provenance{1} = 'INVENTED:no-source-fabricated';
