    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_bad0'), bad, meta);
    T = T.chk(false, 'invented provenance class errors');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_writer:provenance'), 'invented class errors phase5b_writer:provenance');
end
% Duty NOTE-row form: legal SOURCE-BACKED prefix with ESTIMATED reference
% in text passes (whitelist checks the class prefix, never the note body).
noteform = tables;
noteform.duty.provenance{1} = ['SOURCE-BACKED:Phase-4-production-import-joined-F3-LLL-total;' ...
    'ESTIMATED:50.00-kA-station-reference-informational-only-never-duty-basis'];
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_noteform'), noteform, meta);
    T = T.chk(true, 'NOTE-row SOURCE-BACKED prefix with ESTIMATED text passes');
catch ME
