end
% Schema guard: effectiveness missing locked column.
bad5 = tables;
bad5.effectiveness = removevars(bad5.effectiveness, 'not_determinable');
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_bad5'), bad5, meta);
    T = T.chk(false, 'effectiveness missing column errors');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_writer:schema'), 'effectiveness missing column errors phase5b_writer:schema');
end
% C3 concern resolved: assumption_class PRIMARY on PHYSICAL row is legal.
T = T.chk(any(strcmp(tables.registry.layer, 'PHYSICAL') & strcmp(tables.registry.assumption_class, 'PRIMARY')), ...
    'tiny registry carries PHYSICAL + PRIMARY row (C3 concern probe present)');
% BLOCKED-evidence pin (read-only source scan, frozen file never modified):
% frozen phase5_sensitivity hard-codes the v1 2000 CT on its upstream leg,
