function [np, nf] = test_phase5b_gate()
%TEST_PHASE5B_GATE  Phase-5b Task C14 extended-gate tests (TDD).
%   Locks interface G = phase5b_gate() / G = phase5b_gate(ov):
%   23-predicate read-only consumer of results/phase5_protection_v2/ +
%   PHASE5_FINAL_REPORT.md + results/phase5_protection/ (v1 untouched spot)
%   + results/phase4_fault/production/ (it modifies nothing); prints a
%   checklist; errors phase5b_gate-prefixed on any fail.
%   Optional struct ov overrides shipped tables/report text in-memory only
%   (negative-path injection); recognised fields: faultInputs,
%   relayCurrents, coordMatrix, coordMargins, duty, sensitivity, settings,
%   registry, validation, effectiveness (MATLAB tables), reportText (char),
%   noThrow (logical: return G without erroring).
%   G struct fields: .n (23), .ids, .pass (logical row), .note (cellstr),
%   .npass.
%   P01-P17 are the v1 17 predicates re-pointed at v2 outputs; B01-B06 are
%   the v2 physical predicates (registry-physical, no-2000, dt-flagged,
%   effectiveness, duty-52G, v1-untouched).
T = t_case('test_phase5b_gate');

% --- Live gate on shipped v2 outputs passes 23/23 ---
G = phase5b_gate();
T = T.chk(isstruct(G) && G.n == 23, 'gate returns struct with n=23 predicates');
T = T.chk(all(G.pass), 'live gate passes all 23 predicates on shipped v2 outputs');
T = T.chk(G.npass == 23, 'live gate npass==23');

% --- Predicate table shape locked ---
T = T.chk(numel(G.ids) == 23 && numel(G.note) == 23, 'ids/notes cover 23 predicates');
T = T.chk(any(strcmp(G.ids, 'regression')) && any(strcmp(G.ids, 'report-match')) ...
    && any(strcmp(G.ids, 'no-Phase3/4-change')), 'key v1 predicate ids present');
T = T.chk(any(strcmp(G.ids, 'registry-physical')) && any(strcmp(G.ids, 'no-2000')) ...
    && any(strcmp(G.ids, 'dt-flagged')) && any(strcmp(G.ids, 'effectiveness')) ...
    && any(strcmp(G.ids, 'duty-52G')) && any(strcmp(G.ids, 'v1-untouched')), ...
    'six B predicate ids present');

% --- Negative path 1: synthetic 2000/1 CT row breaks no-2000 ---
root = ashuganj_root();
Rg = readtable(fullfile(root, 'results', 'phase5_protection_v2', ...
    'phase5_device_registry.csv'), 'Delimiter', ',');
Rg.ct_ratio(1) = 2000;
ov = struct('registry', Rg, 'noThrow', true);
Gn = phase5b_gate(ov);
hit = strcmp(Gn.ids, 'no-2000');
T = T.chk(~Gn.pass(hit), 'synthetic 2000 CT fails no-2000 predicate');
T = T.chk(Gn.npass < 23, 'synthetic 2000 CT reduces npass below 23');
try
    phase5b_gate(struct('registry', Rg));
    T = T.chk(false, 'throwing gate must error on synthetic 2000 CT');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_gate', 12), ...
        'gate failure error is phase5b_gate-prefixed');
end

% --- Negative path 2: shifted F3 value breaks regression ---
Fd = readtable(fullfile(root, 'results', 'phase5_protection_v2', ...
    'phase5_fault_inputs.csv'), 'Delimiter', ',');
rF3 = strcmp(Fd.fault_location, 'F3') & strcmp(Fd.fault_type, 'LLL') ...
    & strcmp(Fd.caseID, 'LF360_GAT_OUT');
Fd.I_primary_kA(rF3) = Fd.I_primary_kA(rF3) + 1.0;
Gn2 = phase5b_gate(struct('faultInputs', Fd, 'noThrow', true));
T = T.chk(~Gn2.pass(strcmp(Gn2.ids, 'regression')), ...
    'shifted F3 LLL value fails regression predicate');
try
    phase5b_gate(struct('faultInputs', Fd));
    T = T.chk(false, 'throwing gate must error on shifted F3');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_gate', 12), ...
        'regression failure error is phase5b_gate-prefixed');
end

[np, nf] = T.done();
end

function [np, nf] = test_phase5b_duty()
%TEST_PHASE5B_DUTY  Phase-5b Task C9 duty correction: 52G rows + equipment/interrupting column split.
%   Locked interface under test: D = phase5b_duty(Tthrough, ratings52G)
%   wraps the FROZEN v1 engine phase5_duty (read-only, never modified) for
%   the Q0 block and adds per-(case,loc,type) 52G rows on the GEN_Q branch
%   (leg_GEN_kA) vs 100 kA sym breaking (SOURCE-BACKED ledger
%   GCB-10BAC10-100kA), plus equipment_rating_kA + equipment_basis columns.
%
%   Locked outcomes (frozen production data):
%     Q0 rows: as in v1, rating_kA NaN, verdict NOT DETERMINABLE FROM
%       AVAILABLE DATA (GIS 50 kA short-time withstand is EQUIPMENT
%       WITHSTAND, master S17 SOURCE-BACKED - never an interrupting rating,
%       so it lives ONLY in the equipment columns).
%     52G rows: equipment NaN (no 52G equipment-withstand sourced) +
%       breaker_interrupting_rating 100 kA; F1 LLL OUT GEN 55.0487 kA -> PASS.
%     IN-case max (honest, whatever the data says): F1/F2 LLL IN GEN
%       54.9411 kA -> PASS; the test recomputes the max from live data and
%       pins the observed value loudly (fails on data change by design).
%     Exactly one 50-kA NOTE row retained; its note text carries separate
%       I_fault_system_reference vs equipment_short_circuit_rating fields
%       (spec S9/S12 system-vs-equipment wording).
%
%   TDD RED note: first run fails with undefined function phase5b_duty
%   as required; GREEN after wrapper creation. v1 phase5_duty.m untouched.
T = t_case('test_phase5b_duty');
root = ashuganj_root();

% --- Synthetic through-table (mirrors v1 duty synthetic + leg_GEN_kA) ---
locs  = {'F1'; 'F3'; 'F4'; 'F5'; 'F4'};
typs  = {'LLL'; 'LLL'; 'LLL'; 'LLL'; 'LL'};
cases = {'CASE_A'; 'CASE_A'; 'CASE_A'; 'CASE_A'; 'CASE_A'};
Itot  = [126.21414119005; 50.5308851865359; 51.058; 53.087; 44.215];
lGRID = [72.105; 47.37; 47.946; 49.941; 0.77298];
lHV   = [72.105; 3.2184; 3.1721; 3.2076; 0.77298];
lTOT  = [72.105; 47.37; 51.058; 3.2076; 1.0912e-13];
lB1   = [NaN; NaN; 14.325; NaN; 0.38649];
lB2   = [NaN; NaN; 36.737; NaN; 0.38649];
lGEN  = [55.049; 3.2285; 3.1826; 3.2177; 0.94037];
pk    = [348.255062723563; 129.76; 131.31; 136.0; 113.71];
Tsyn = table(locs, typs, cases, Itot, lGRID, lHV, lTOT, lB1, lB2, lGEN, pk, ...
    'VariableNames', {'fault_location', 'fault_type', 'caseID', 'I_primary_kA', ...
    'leg_GRID_kA', 'leg_GSUT_HV_kA', 'leg_LINE_total_kA', 'leg_LINE_B1_kA', ...
    'leg_LINE_B2_kA', 'leg_GEN_kA', 'r_kappa_ip'});

% --- Module call: default 52G rating (100 kA SOURCE-BACKED ledger) ---
D = phase5b_duty(Tsyn);

% --- Locked 12-col schema: v1 10 + equipment split ---
exp12 = {'location', 'breaker_ref', 'fault_type', 'caseID', 'I_sym_kA', ...
    'I_peak_kA', 'rating_kA', 'basis', 'verdict', 'note', ...
    'equipment_rating_kA', 'equipment_basis'};
T = T.chk(istable(D), 'D is a table');
T = T.chk(isequal(D.Properties.VariableNames, exp12), 'duty exact 12-col schema in locked order');
T = T.chk(~any(strcmp(D.Properties.VariableNames, 't_up_s')) && ...
    ~any(strcmp(D.Properties.VariableNames, 'margin_s')), 'duty stays separate from coordination');

% --- Row partition: n Q0 + n 52G + exactly one NOTE ---
n = height(Tsyn);
isNote = strcmp(D.verdict, 'NOTE');
isQ0 = strcmp(D.breaker_ref, 'Q0') & ~isNote;
is52 = strcmp(D.breaker_ref, '52G');
T = T.chk(sum(isNote) == 1, 'exactly one NOTE row retained');
T = T.chk(sum(isQ0) == n, 'Q0 block has one row per input row');
T = T.chk(sum(is52) == n, '52G block has one row per input row');
