T = T.chk(height(qF4) == 1 && abs(qF4.I_sym_kA - 3.1721) < 1e-9, 'Q0 F4 LLL through-current 3.1721 kA (frozen-engine identity)');
qF1 = Q0(strcmp(Q0.location, 'F1'), :);
T = T.chk(height(qF1) == 1 && abs(qF1.I_sym_kA - 72.105) < 1e-9, 'Q0 F1 LLL through-current 72.105 kA (frozen-engine identity)');

% --- Q0 equipment columns: GIS 50 kA withstand, never interrupting ---
T = T.chk(all(abs(Q0.equipment_rating_kA - 50) < 1e-12), 'Q0 equipment_rating_kA == 50 (GIS short-time withstand)');
T = T.chk(all(~cellfun(@isempty, strfind(Q0.equipment_basis, 'EQUIPMENT WITHSTAND'))), ...
