T = T.chk(all(~cellfun(@isempty, strfind(Q0.equipment_basis, 'never interrupting'))), ...
    'Q0 equipment_basis states never interrupting');
T = T.chk(all(~cellfun(@isempty, strfind(Q0.equipment_basis, 'SOURCE-BACKED'))), ...
    'Q0 equipment_basis SOURCE-BACKED (master S17)');

% --- 52G rows: GEN_Q branch vs 100 kA interrupting; equipment NaN ---
G = D(is52, :);
T = T.chk(all(abs(G.rating_kA - 100) < 1e-12), '52G rating_kA == 100 (GCB-10BAC10 sym breaking)');
T = T.chk(all(isnan(G.equipment_rating_kA)), '52G equipment_rating_kA NaN (no 52G equipment-withstand sourced)');
T = T.chk(all(~cellfun(@isempty, strfind(G.basis, 'GCB-10BAC10'))), '52G basis traces GCB-10BAC10 ledger entry');
T = T.chk(all(~cellfun(@isempty, strfind(G.basis, 'SOURCE-BACKED'))), '52G basis SOURCE-BACKED');
gF1 = G(strcmp(G.location, 'F1') & strcmp(G.fault_type, 'LLL') & strcmp(G.caseID, 'CASE_A'), :);
T = T.chk(height(gF1) == 1 && abs(gF1.I_sym_kA - 55.049) < 1e-9, '52G F1 LLL I_sym 55.049 kA (GEN_Q branch, not 126.21 total)');
T = T.chk(strcmp(gF1.verdict{1}, 'PASS'), '52G F1 LLL 55.049 kA <= 100 kA -> PASS');
T = T.chk(abs(gF1.I_peak_kA - 348.255062723563) < 1e-9, '52G peak passthrough informational only');
% 52G equipment basis: no withstand invented, interrupting/equipment split stated.
T = T.chk(all(~cellfun(@isempty, strfind(G.equipment_basis, 'MISSING'))), '52G equipment_basis MISSING (no withstand sourced)');
% Total-current doctrine: 52G never uses the bus total.
T = T.chk(abs(gF1.I_sym_kA - 126.21414119005) > 1, '52G F1 uses GEN_Q branch, never the 126.21 bus total');

% --- GIS-50kA scan: withstand lives ONLY in equipment columns ---
% rating_kA domain over the whole table: NaN (Q0 duty) / 100 (52G) / 50 (NOTE reference only).
rv = D.rating_kA;
T = T.chk(all(isnan(rv) | abs(rv - 100) < 1e-12 | abs(rv - 50) < 1e-12), 'rating_kA domain is NaN/100/50-only');
T = T.chk(all(isnan(rv(isQ0))), 'GIS-50kA never appears as a Q0 interrupting rating (scan)');
T = T.chk(~table_has_str(Q0(:, {'location', 'breaker_ref', 'fault_type', 'caseID', 'basis', 'verdict', 'note'}), '50 kA sym breaking'), ...
    'no 50 kA sym-breaking claim on Q0 rows (scan)');
T = T.chk(~table_has_str(D(:, {'location', 'breaker_ref', 'fault_type', 'caseID', 'rating_kA', 'basis', 'verdict', 'note'}), 'EQUIPMENT WITHSTAND'), ...
    'EQUIPMENT WITHSTAND wording lives only in equipment columns (scan)');

% --- MISSING 52G rating path: [] -> NOT DETERMINABLE, never invented ---
Dm = phase5b_duty(Tsyn, []);
Gm = Dm(strcmp(Dm.breaker_ref, '52G'), :);
T = T.chk(all(strcmp(Gm.verdict, 'NOT DETERMINABLE FROM AVAILABLE DATA')), 'MISSING 52G rating -> NOT DETERMINABLE');
T = T.chk(all(isnan(Gm.rating_kA)), 'MISSING 52G rating -> rating NaN');
T = T.chk(all(~cellfun(@isempty, strfind(Gm.basis, 'MISSING'))), 'MISSING 52G rating -> basis carries MISSING tag');
Q0m = Dm(strcmp(Dm.breaker_ref, 'Q0') & ~strcmp(Dm.verdict, 'NOTE'), :);
T = T.chk(all(isnan(Q0m.rating_kA)) && all(abs(Q0m.equipment_rating_kA - 50) < 1e-12), ...
    'MISSING rating path keeps Q0 rating NaN + equipment 50');

% --- 50-kA NOTE row retained with system-vs-equipment wording ---
nRow = D(isNote, :);
T = T.chk(abs(nRow.I_sym_kA - 50.5308851865359) < 1e-6, 'NOTE row I_sym 50.53 kA (F3 LLL reference)');
T = T.chk(abs(nRow.rating_kA - 50.0) < 1e-12, 'NOTE row estimated reference 50.00 kA retained');
T = T.chk(~strcmp(nRow.verdict{1}, 'PASS') && ~strcmp(nRow.verdict{1}, 'FAIL'), 'NOTE row never PASS/FAIL');
T = T.chk(~isempty(strfind(nRow.note{1}, 'I_fault_system_reference')), 'NOTE note carries I_fault_system_reference field');
T = T.chk(~isempty(strfind(nRow.note{1}, 'equipment_short_circuit_rating')), 'NOTE note carries equipment_short_circuit_rating field');
T = T.chk(abs(nRow.equipment_rating_kA - 50) < 1e-12, 'NOTE equipment_rating_kA 50 (equipment side of the split)');
T = T.chk(all(~cellfun(@isempty, strfind(nRow.equipment_basis, 'EQUIPMENT WITHSTAND'))), 'NOTE equipment_basis states EQUIPMENT WITHSTAND');

% --- Live-data integration (honest backbone leg join, read-only) ---
Ti = phase5_import(root);
T = T.chk(height(Ti) == 40, 'T40 backbone has 40 rows (2x5x4)');
Di = phase5b_duty(Ti);
T = T.chk(height(Di) == 2 * height(Ti) + 1, 'live duty rows = 2x import rows + exactly one NOTE row');
Gi = Di(strcmp(Di.breaker_ref, '52G'), :);
Qi = Di(strcmp(Di.breaker_ref, 'Q0') & ~strcmp(Di.verdict, 'NOTE'), :);
