T = T.chk(all(abs(Gi.rating_kA - 100) < 1e-12), 'live 52G rating 100');
% F1 LLL OUT 52G PASS (55.0487 kA live anchor).
rOUT = Gi(strcmp(Gi.location, 'F1') & strcmp(Gi.fault_type, 'LLL') & strcmp(Gi.caseID, 'LF360_GAT_OUT'), :);
T = T.chk(height(rOUT) == 1, 'live F1 LLL OUT 52G row present');
T = T.chk(abs(rOUT.I_sym_kA - 55.0487) < 1e-3, 'live F1 LLL OUT GEN_Q 55.0487 kA');
T = T.chk(strcmp(rOUT.verdict{1}, 'PASS'), 'live F1 LLL OUT 52G PASS (55.05 kA <= 100 kA)');
% IN-case max documented honestly: recomputed from live data, pinned loudly.
inG = Gi(strcmp(Gi.caseID, 'LF360_GAT_IN'), :).I_sym_kA;
inMax = max(inG);
T = T.chk(abs(inMax - 54.9411) < 1e-3, sprintf('honest IN-case 52G max %.4f kA (F1/F2 LLL IN anchor)', inMax));
hitMax = Gi(strcmp(Gi.caseID, 'LF360_GAT_IN') & abs(Gi.I_sym_kA - inMax) < 1e-9, :);
T = T.chk(all(strcmp(hitMax.verdict, 'PASS')), 'IN-case max row(s) PASS vs 100 kA (honest, never tuned)');
T = T.chk(all(Gi.I_sym_kA <= 100), 'all live 52G duties <= 100 kA (PASS across backbone)');
% Live NOTE row wording.
niRow = Di(strcmp(Di.verdict, 'NOTE'), :);
T = T.chk(height(niRow) == 1 && ~isempty(strfind(niRow.note{1}, 'I_fault_system_reference')) && ...
    ~isempty(strfind(niRow.note{1}, 'equipment_short_circuit_rating')), 'live NOTE row carries split-field wording');

% --- Errors phase5b-prefixed ---
try
    phase5b_duty(table(), []);
    T = T.chk(false, 'empty table must error');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_duty', 12), 'empty-table error is phase5b_duty-prefixed');
end
try
    phase5b_duty(Tsyn, struct('breaker_ref', 'Q0', 'rating_kA', 50.0, 'source', 'STUDY:x'));
    T = T.chk(false, 'Q0 rating must error (50 kA withstand never an interrupting rating)');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_duty', 12), 'Q0-rating error is phase5b_duty-prefixed');
end
try
    phase5b_duty(Tsyn, struct('breaker_ref', 'Q9', 'rating_kA', 40.0, 'source', 'STUDY:x'));
    T = T.chk(false, 'Q9 rating must error (disconnectors never duty)');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_duty', 12), 'Q9-rating error is phase5b_duty-prefixed');
end
try
    TnoGen = removevars(Tsyn, 'leg_GEN_kA');
    phase5b_duty(TnoGen);
    T = T.chk(false, 'missing leg_GEN_kA must error (GEN_Q required for 52G)');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_duty', 12), 'missing-GEN-leg error is phase5b_duty-prefixed');
end

[np, nf] = T.done();
end

function tf = table_has_str(D, pat)
%TABLE_HAS_STR  True if pattern appears in any variable name or string cell of D.
tf = ~isempty(strfind(strjoin(D.Properties.VariableNames, '|'), pat));
if tf, return; end
for k = 1:numel(D.Properties.VariableNames)
    col = D.(D.Properties.VariableNames{k});
    if iscell(col)
        for i = 1:numel(col)
            v = col{i};
            if (ischar(v) || isstring(v)) && ~isempty(strfind(char(v), pat))
                tf = true; return;
            end
        end
    elseif ischar(col) || isstring(col)
        if ~isempty(strfind(char(col), pat)), tf = true; return; end
    elseif isnumeric(col)
        continue;
    end
end
end

